/* Tech 3D · Nivell 1 · unitat 3 «Moure, girar i escalar» · guia del professor (m3-1 … m3-4)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1']. Les diapositives «media» mostren el
   model en 3D (TMEDIA.model): a la pissarra digital es pot girar amb el dit o amb el ratolí. */
Object.assign(TGUIDE, (() => {
  const P = (id, t, s, p, c, o = {}) => ({ id, t, s, p, r: o.r || [0, 0, 0], c, ...o });
  const B = (id, t, s, x, y, z0, c, o = {}) => P(id, t, s, [x, y, z0 + (o.h ?? s[2]) / 2], c, o);
  const cub = (x, y, id, c = '#7C5CFF', m = 20) => B(id, 'box', [m, m, m], x, y, 0, c);
  const CAPSA = B('capsa', 'box', [40, 30, 16], 0, 0, 0, '#F5893A');
  const CARA = [B('cap', 'box', [30, 20, 20], 0, 0, 0, '#5BC0EB'), B('boca', 'box', [14, 2, 3], 0, -10, 5, '#2A2F3A'), B('u1', 'sph', [6, 6, 6], -8, -10, 10, '#2A2F3A'), B('u2', 'sph', [6, 6, 6], 8, -10, 10, '#2A2F3A')];
  const bar = (id, x, y, rz, c, l = 50) => B(id, 'box', [l, 10, 10], x, y, 0, c, { r: [0, 0, rz] });
  const roda = (id, x) => B(id, 'cyl', [16, 16, 6], x, 0, 0, '#2A2F3A', { r: [0, 90, 0], h: 16 });
  const ARBRE = (x, k, id) => [B(id + 't', 'cyl', [6 * k, 6 * k, 10 * k], x, 0, 0, '#A0683A'), B(id + 'c', 'cone', [16 * k, 16 * k, 16 * k], x, 0, 10 * k, '#2FB36D')];
  const ROBOT = [roda('r1', -16), roda('r2', 16), B('cos', 'box', [26, 18, 24], 0, 0, 4, '#7C5CFF'), B('b1', 'box', [6, 6, 20], -23, 0, 20, '#FF8A3D', { r: [0, 90, 0], h: 6 }), B('b2', 'box', [6, 6, 20], 23, 0, 20, '#FF8A3D', { r: [0, 90, 0], h: 6 }),
    B('cap', 'box', [20, 16, 14], 0, 0, 28, '#5BC0EB'), B('u1', 'sph', [6, 6, 6], -5, -8, 32, '#2A2F3A'), B('u2', 'sph', [6, 6, 6], 5, -8, 32, '#2A2F3A'), B('antena', 'cyl', [2, 2, 8], 0, 0, 42, '#9AA3B5'), B('bola', 'sph', [6, 6, 6], 0, 0, 50, '#E8453C')];
  return {
  /* ---------- Sessió 1 · Moure amb precisió ---------- */
  'm3-1': {
    intro: "Comença la unitat del robot de peces. Fins ara l'alumnat col·locava peces a ull o amb coordenades rodones; avui aprèn a moure-les amb precisió de mil·límetre. Hi ha tres idees: arrossegar és ràpid però aproximat, els números són exactes, i la quadrícula magnètica (1, 5 o 10 mm) decideix on pot aterrar una peça quan s'arrossega. La idea matemàtica central és que moure és sumar o restar a la coordenada que ja hi ha, també amb nombres negatius.|Empieza la unidad del robot de piezas. Hasta ahora el alumnado colocaba piezas a ojo o con coordenadas redondas; hoy aprende a moverlas con precisión de milímetro. Hay tres ideas: arrastrar es rápido pero aproximado, los números son exactos, y la cuadrícula magnética (1, 5 o 10 mm) decide dónde puede aterrizar una pieza cuando se arrastra. La idea matemática central es que mover es sumar o restar a la coordenada que ya hay, también con números negativos.",
    claus: ["Arrossegar porta la peça a prop; els números de la pestanya Posició la deixen exacta.|Arrastrar lleva la pieza cerca; los números de la pestaña Posición la dejan exacta.",
      "La quadrícula magnètica fa saltar la peça de 10, 5 o 1 mm: el salt decideix a quins punts pot arribar.|La cuadrícula magnética hace saltar la pieza de 10, 5 o 1 mm: el salto decide a qué puntos puede llegar.",
      "Moure és sumar (dreta, fons, amunt) o restar (esquerra, davant, avall) a la coordenada que ja hi ha.|Mover es sumar (derecha, fondo, arriba) o restar (izquierda, delante, abajo) a la coordenada que ya hay.",
      "La impressora fabrica exactament el que dibuixem: 2 o 3 mm de desviació fan que una tapa no tanqui.|La impresora fabrica exactamente lo que dibujamos: 2 o 3 mm de desviación hacen que una tapa no cierre."],
    prev: ["Llegir coordenades x, y, z i nombres negatius (unitat 1, sessió 3).|Leer coordenadas x, y, z y números negativos (unidad 1, sesión 3).", "Saber que la z de la pestanya Posició és l'alçada de la base.|Saber que la z de la pestaña Posición es la altura de la base.", "Sumar i restar nombres de dues xifres.|Sumar y restar números de dos cifras."],
    obj: ["L'alumne/a col·loca una peça en una posició exacta escrivint x, y i z a la pestanya Posició.|El alumno/a coloca una pieza en una posición exacta escribiendo x, y y z en la pestaña Posición.",
      "L'alumne/a tria el salt de la quadrícula (1, 5 o 10 mm) segons la precisió que necessita.|El alumno/a elige el salto de la cuadrícula (1, 5 o 10 mm) según la precisión que necesita.",
      "L'alumne/a calcula la posició nova d'una peça després d'un moviment, també amb nombres negatius.|El alumno/a calcula la posición nueva de una pieza después de un movimiento, también con números negativos.",
      "L'alumne/a detecta i corregeix peces mal col·locades per pocs mil·límetres.|El alumno/a detecta y corrige piezas mal colocadas por pocos milímetros."],
    comp: ["Matemàtiques, sentit espacial: posició i desplaçament en el pla i en l'espai amb coordenades|Matemáticas, sentido espacial: posición y desplazamiento en el plano y en el espacio con coordenadas",
      "Matemàtiques, sentit numèric: sumar i restar amb nombres enters (negatius)|Matemáticas, sentido numérico: sumar y restar con números enteros (negativos)",
      "Matemàtiques, sentit de la mesura: el mil·límetre com a unitat de precisió|Matemáticas, sentido de la medida: el milímetro como unidad de precisión",
      "Tecnologia i digitalització: precisió en el disseny assistit per ordinador i la fabricació digital|Tecnología y digitalización: precisión en el diseño asistido por ordenador y la fabricación digital"],
    vocab: [['Precisió|Precisión', 'Fer una cosa exactament on i com toca, sense desviar-se.|Hacer algo exactamente donde y como toca, sin desviarse.'], ['Desplaçament|Desplazamiento', "El moviment d'una peça: quants mil·límetres i cap a on.|El movimiento de una pieza: cuántos milímetros y hacia dónde."],
      ['Quadrícula magnètica|Cuadrícula magnética', "Fa que la peça salti de punt en punt (1, 5 o 10 mm) quan s'arrossega.|Hace que la pieza salte de punto en punto (1, 5 o 10 mm) cuando se arrastra."], ['Pestanya Posició|Pestaña Posición', 'On s\'escriuen la x i la y del centre i la z de la base d\'una peça.|Donde se escriben la x y la y del centro y la z de la base de una pieza.'],
      ['Fantasma|Fantasma', 'El model transparent que marca on ha d\'anar la peça.|El modelo transparente que marca dónde tiene que ir la pieza.'], ['Nombre negatiu|Número negativo', "Un nombre més petit que 0: a l'esquerra o davant de l'origen.|Un número menor que 0: a la izquierda o delante del origen."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Moure amb precisió»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Mover con precisión»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "Per parella: un regle, una goma d'esborrar i un full quadriculat amb els eixos dibuixats (la placa de paper)|Por pareja: una regla, una goma de borrar y una hoja cuadriculada con los ejes dibujados (la placa de papel)"],
      imprimir: ['Targetes de moviments|Tarjetas de movimientos', 'Fitxa: on queda la peça?|Ficha: ¿dónde queda la pieza?'],
      prep: ["Imprimir i retallar les targetes de moviments (un conjunt per parella).|Imprimir y recortar las tarjetas de movimientos (un conjunto por pareja).", 'Preparar un full quadriculat per parella amb dues línies que es creuen al mig (x i y) i el 0 marcat.|Preparar una hoja cuadriculada por pareja con dos líneas que se cruzan en el medio (x e y) y el 0 marcado.', "Provar el repte dels ulls del robot: cal escriure tres números per ull.|Probar el reto de los ojos del robot: hay que escribir tres números por ojo."] },
    plan: [
      { min: 5, t: "L'encàrrec del robot|El encargo del robot", fase: 'inici', fa: "Presenta l'encàrrec de la unitat: l'escola del barri vol un robot de peces per a la Setmana de la Robòtica i ens envia una fitxa amb mides en mil·límetres. Planteja el problema: com li diem a la Nuvi «una mica més a la dreta»?|Presenta el encargo de la unidad: la escuela del barrio quiere un robot de piezas para la Semana de la Robótica y nos envía una ficha con medidas en milímetros. Plantea el problema: ¿cómo le decimos a Nuvi «un poco más a la derecha»?",
        diu: ['Què vol dir «una mica»? Quants mil·límetres són?|¿Qué quiere decir «un poco»? ¿Cuántos milímetros son?', 'Per què una impressora necessita números exactes?|¿Por qué una impresora necesita números exactos?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Arrossegar, saltar i sumar|Arrastrar, saltar y sumar', fase: 'teoria', fa: "Explica les dues maneres de moure (dit i números) amb el fantasma. Mostra la quadrícula magnètica: per què amb salts de 10 mm no s'arriba a 37 mm. Dedica temps a «moure és sumar»: fes exemples a la pissarra, també cap a l'esquerra (restar) i passant pel zero. Acaba amb la tapa desplaçada: per què importa la precisió.|Explica las dos maneras de mover (dedo y números) con el fantasma. Muestra la cuadrícula magnética: por qué con saltos de 10 mm no se llega a 37 mm. Dedica tiempo a «mover es sumar»: haz ejemplos en la pizarra, también hacia la izquierda (restar) y pasando por el cero. Acaba con la tapa desplazada: por qué importa la precisión.",
        diu: ['Si és a x = 10 i la moc 25 mm a la dreta, on queda? I si la moc a l\'esquerra?|Si está en x = 10 y la muevo 25 mm a la derecha, ¿dónde queda? ¿Y si la muevo a la izquierda?', 'Quin salt triaríeu per arribar a 35? I a 37?|¿Qué salto elegiríais para llegar a 35? ¿Y a 37?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'El dictat de moviments|El dictado de movimientos', fase: 'desconnectat', fa: "Per parelles, amb la placa de paper i una goma que fa de peça. Una persona treu tres targetes de moviment i les llegeix; l'altra mou la goma amb el regle. Abans de mesurar, calculen junts on hauria de quedar. Després es canvien els papers.|Por parejas, con la placa de papel y una goma que hace de pieza. Una persona saca tres tarjetas de movimiento y las lee; la otra mueve la goma con la regla. Antes de medir, calculan juntos dónde debería quedar. Después se cambian los papeles.",
        diu: ['Primer feu el càlcul i després mesureu: coincideix?|Primero haced el cálculo y después medid: ¿coincide?', 'Un moviment de −20 en y, cap a on va?|Un movimiento de −20 en y, ¿hacia dónde va?'], slides: ['s8'], app: 'Encara no: activitat a la taula.|Todavía no: actividad en la mesa.', org: 'Per parelles|Por parejas' },
      { min: 20, t: "A l'ordinador: col·loca al mil·límetre|En el ordenador: coloca al milímetro", fase: 'ordinador', fa: "Fan la sessió a l'app fins als reptes. Passa per les taules al repte dels ulls: és el primer cop que escriuen x, y i z per a una peça petita. Vigila que no ho facin tot arrossegant: la comprovació és molt exigent i els números són més ràpids. Als que acaben, proposa la torre de precisió.|Hacen la sesión en la app hasta los retos. Pasa por las mesas en el reto de los ojos: es la primera vez que escriben x, y y z para una pieza pequeña. Vigila que no lo hagan todo arrastrando: la comprobación es muy exigente y los números son más rápidos. A quienes acaben, proponles la torre de precisión.",
        diu: ['Quina x tenia abans? Quant l\'has de moure?|¿Qué x tenía antes? ¿Cuánto la tienes que mover?', 'Mira la comprovació: quin número falla?|Mira la comprobación: ¿qué número falla?'], slides: ['s9', 's10', 's11'], app: 'Sessió «Moure amb precisió», fins a «La teva inicial».|Sesión «Mover con precisión», hasta «Tu inicial».', org: 'Individual|Individual' },
      { min: 8, t: 'La teva inicial|Tu inicial', fase: 'crea', fa: "Cada alumne/a construeix la inicial del seu nom amb peces que es toquin sense espais. La comprovació «una sola peça» els obliga a afinar: si hi ha 1 mm d'espai entre dues barres, no passa. Es desa al portafoli.|Cada alumno/a construye la inicial de su nombre con piezas que se toquen sin espacios. La comprobación «una sola pieza» les obliga a afinar: si hay 1 mm de espacio entre dos barras, no pasa. Se guarda en el portafolio.",
        diu: ['On s\'acaba aquesta barra? On ha de començar la següent?|¿Dónde acaba esta barra? ¿Dónde tiene que empezar la siguiente?'], slides: ['s12'], app: 'Pas «La teva inicial».|Paso «Tu inicial».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa les tres idees (dit o números, salts de la quadrícula, moure és sumar) i fes el tiquet de sortida.|Repasa las tres ideas (dedo o números, saltos de la cuadrícula, mover es sumar) y haz el ticket de salida.',
        diu: ['Quin salt feu servir per afinar? Per què?|¿Qué salto usáis para afinar? ¿Por qué?'], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Escriu la distància del moviment en lloc de la posició nova (posa 25 en lloc de 35).|Escribe la distancia del movimiento en lugar de la posición nueva (pone 25 en lugar de 35).", "Pregunta-li on era la peça abans i fes-li dir el càlcul en veu alta: «era a 10, li sumo 25».|Pregúntale dónde estaba la pieza antes y hazle decir el cálculo en voz alta: «estaba en 10, le sumo 25»."],
      ["S'equivoca de signe en moure cap a l'esquerra o cap a davant.|Se equivoca de signo al mover hacia la izquierda o hacia delante.", "Fes-li seguir la recta amb el dit: cap a l'esquerra els nombres baixen i, passat el zero, porten un menys.|Hazle seguir la recta con el dedo: hacia la izquierda los números bajan y, pasado el cero, llevan un menos."],
      ["Arrossega una vegada i una altra i la peça no arriba mai al fantasma.|Arrastra una y otra vez y la pieza nunca llega al fantasma.", "Mira el salt de la quadrícula: si és de 10 mm i el fantasma és a 35, no hi arribarà. Que canviï el salt o escrigui el número.|Mira el salto de la cuadrícula: si es de 10 mm y el fantasma está en 35, no llegará. Que cambie el salto o escriba el número."],
      ["Als ulls, posa la y del centre a −13 o la z a 13 (barreja centre i base).|En los ojos, pone la y del centro en −13 o la z en 13 (mezcla centro y base).", "Recorda: x i y són el centre de la peça; z és on comença per baix. Fes-li mirar la peça des del costat.|Recuerda: x e y son el centro de la pieza; z es donde empieza por abajo. Hazle mirar la pieza desde el lado."]],
    diff: { mes: "Fer la torre de precisió i després inventar un dictat de 5 moviments per a un company, amb la solució calculada. Construir la inicial amb peces de mides no rodones (12, 17 mm) que encaixin al mil·límetre.|Hacer la torre de precisión y después inventar un dictado de 5 movimientos para un compañero, con la solución calculada. Construir la inicial con piezas de medidas no redondas (12, 17 mm) que encajen al milímetro.",
      menys: "Treballar amb el salt de 5 mm i fantasmes en múltiples de 5. Al dictat, només moviments en x. Tenir una recta numèrica de −50 a 50 a la taula per comptar.|Trabajar con el salto de 5 mm y fantasmas en múltiplos de 5. En el dictado, solo movimientos en x. Tener una recta numérica de −50 a 50 en la mesa para contar." },
    aval: { ticket: ['Una peça és a x = 15 i la mous 20 mm a l\'esquerra. On queda?|Una pieza está en x = 15 y la mueves 20 mm a la izquierda. ¿Dónde queda?', 'Quin salt de la quadrícula fas servir per afinar?|¿Qué salto de la cuadrícula usas para afinar?'],
      rubric: [['Col·locar amb números|Colocar con números', 'Escriu x, y i z exactes i la peça queda al fantasma.|Escribe x, y y z exactos y la pieza queda en el fantasma.', 'Arrossega i hi arriba a prop, però necessita ajuda amb els camps.|Arrastra y llega cerca, pero necesita ayuda con los campos.'],
        ['Calcular moviments|Calcular movimientos', 'Calcula la posició nova sumant o restant, també amb negatius.|Calcula la posición nueva sumando o restando, también con negativos.', "S'equivoca de signe o escriu la distància en lloc de la posició.|Se equivoca de signo o escribe la distancia en lugar de la posición."],
        ['Precisió|Precisión', 'Detecta desviacions de pocs mil·límetres i les corregeix.|Detecta desviaciones de pocos milímetros y las corrige.', 'Ho dona per bo quan és «a prop».|Lo da por bueno cuando está «cerca».']] },
    casa: "Prova «on és el tresor?» en paper: dibuixa una quadrícula amb els eixos al mig, amaga-hi un punt i dona a algú de casa tres moviments per arribar-hi des de l'origen. Ho ha trobat?|Prueba «¿dónde está el tesoro?» en papel: dibuja una cuadrícula con los ejes en el medio, esconde un punto y da a alguien de casa tres movimientos para llegar desde el origen. ¿Lo ha encontrado?",
    faq: [["Per què la comprovació no es marca si la peça ja és al fantasma?|¿Por qué la comprobación no se marca si la pieza ya está en el fantasma?", "Perquè hi ha de ser gairebé exacta (menys d'1 mm de diferència). Amb el dit sovint queda a 1 o 2 mm: cal mirar els números de Posició.|Porque tiene que estar casi exacta (menos de 1 mm de diferencia). Con el dedo a menudo queda a 1 o 2 mm: hay que mirar los números de Posición."],
      ['Per què la z és la base i la x i la y són el centre?|¿Por qué la z es la base y la x y la y son el centro?', "Perquè és el més pràctic: per posar una peça a sobre d'una altra, n'hi ha prou de saber on s'acaba la de sota; i per centrar-la, el centre.|Porque es lo más práctico: para poner una pieza encima de otra, basta con saber dónde acaba la de debajo; y para centrarla, el centro."],
      ['Es poden escriure decimals?|¿Se pueden escribir decimales?', "Sí (per exemple, 12,5), però en aquest curs procurem que les mides siguin nombres enters: són més fàcils de comprovar.|Sí (por ejemplo, 12,5), pero en este curso procuramos que las medidas sean números enteros: son más fáciles de comprobar."]],
    tec: [["La peça es mou a salts massa grans quan s'arrossega.|La pieza se mueve a saltos demasiado grandes cuando se arrastra.", "El botó ⊞ mm de sota la vista canvia el salt: 1, 5 o 10 mm. Cada toc passa al següent.|El botón ⊞ mm de debajo de la vista cambia el salto: 1, 5 o 10 mm. Cada toque pasa al siguiente."],
      ["En escriure el número, no canvia res.|Al escribir el número, no cambia nada.", "Cal prémer Retorn o tocar fora del camp perquè s'apliqui. Si hi ha una lletra o un espai, el camp no l'accepta.|Hay que pulsar Intro o tocar fuera del campo para que se aplique. Si hay una letra o un espacio, el campo no lo acepta."],
      ['Amb les fletxes del teclat no es mou res.|Con las flechas del teclado no se mueve nada.', "Primer cal tocar la peça perquè quedi triada, i el cursor no ha d'estar dins d'un camp numèric.|Primero hay que tocar la pieza para que quede seleccionada, y el cursor no tiene que estar dentro de un campo numérico."]],
    extra: ["Fer un «dictat a cegues»: una persona descriu una figura de 3 peces només amb coordenades i l'altra la construeix a l'app.|Hacer un «dictado a ciegas»: una persona describe una figura de 3 piezas solo con coordenadas y la otra la construye en la app.", "Mesurar al mil·límetre objectes petits de l'aula (una goma, una peça de construcció) i comparar mesures entre companys.|Medir al milímetro objetos pequeños del aula (una goma, una pieza de construcción) y comparar medidas entre compañeros.", "Buscar on cal precisió a la vida real: les tapes dels pots, les peces d'un trencaclosques, les claus.|Buscar dónde hace falta precisión en la vida real: las tapas de los botes, las piezas de un rompecabezas, las llaves."],
    trans: ['Sessió següent: girar peces (15°, 45° i 90°) per fer els braços i les rodes del robot.|Sesión siguiente: girar piezas (15°, 45° y 90°) para hacer los brazos y las ruedas del robot.', 'Matemàtiques: suma i resta de nombres enters a la recta numèrica.|Matemáticas: suma y resta de números enteros en la recta numérica.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Moure amb precisió|Mover con precisión', x: "Al mil·límetre, perquè la Nuvi ho imprimeixi bé|Al milímetro, para que Nuvi lo imprima bien", nota: "Presenta l'encàrrec: un robot de peces per a l'escola, amb una fitxa de mides en mil·límetres.|Presenta el encargo: un robot de piezas para la escuela, con una ficha de medidas en milímetros." },
      { id: 's2', k: 'pregunta', t: '«Una mica més a la dreta»: quant és?|«Un poco más a la derecha»: ¿cuánto es?', x: 'Com li ho diríeu a una impressora?|¿Cómo se lo diríais a una impresora?', nota: "Recull respostes. Busquem que diguin que cal un número exacte i una direcció.|Recoge respuestas. Buscamos que digan que hace falta un número exacto y una dirección." },
      { id: 's3', k: 'media', t: 'Dues maneres de moure|Dos maneras de mover', x: 'Arrossegar per apropar-se; números per deixar-la exacta.|Arrastrar para acercarse; números para dejarla exacta.', media: { k: 'model', model: { parts: [cub(-30, 10, 'q')] }, target: { parts: [cub(25, -15, 'g')] } }, nota: "Mostra el fantasma i pregunta quins números caldria escriure (x = 25, y = −15).|Muestra el fantasma y pregunta qué números habría que escribir (x = 25, y = −15)." },
      { id: 's4', k: 'anim', t: 'La quadrícula magnètica|La cuadrícula magnética', anim: 'm31snap', x: 'Amb salts de 10 o 5 mm no s\'arriba a 37 mm. Amb 1 mm, sí.|Con saltos de 10 o 5 mm no se llega a 37 mm. Con 1 mm, sí.', nota: "Pregunta a quins punts s'hi arriba amb cada salt: 10 mm, només múltiples de 10; 5 mm, múltiples de 5.|Pregunta a qué puntos se llega con cada salto: 10 mm, solo múltiplos de 10; 5 mm, múltiplos de 5." },
      { id: 's5', k: 'anim', t: 'Moure és sumar|Mover es sumar', anim: 'm31mou', x: 'De x = 10 a x = 35: +25 mm.|De x = 10 a x = 35: +25 mm.', nota: "Fes dos o tres exemples més a la pissarra, un cap a l'esquerra.|Haz dos o tres ejemplos más en la pizarra, uno hacia la izquierda." },
      { id: 's6', k: 'pregunta', t: 'Una peça a x = 10 es mou 25 mm a l\'esquerra. On queda?|Una pieza en x = 10 se mueve 25 mm a la izquierda. ¿Dónde queda?', x: 'Pista: passa pel zero.|Pista: pasa por el cero.', nota: 'Resposta: x = −15 (10 − 25). Dibuixa la recta i compta junts.|Respuesta: x = −15 (10 − 25). Dibuja la recta y contad juntos.' },
      { id: 's7', k: 'media', t: 'Per què tanta precisió?|¿Por qué tanta precisión?', x: 'Una tapa desplaçada 3 mm no tanca.|Una tapa desplazada 3 mm no cierra.', media: { k: 'model', model: { parts: [CAPSA, B('tapa', 'box', [42, 32, 4], 3, -2, 16, '#E8453C')] } }, nota: "Gira el model: la tapa sobresurt per la dreta i per davant. La impressora no ho arregla.|Gira el modelo: la tapa sobresale por la derecha y por delante. La impresora no lo arregla." },
      { id: 's8', k: 'activitat', t: 'El dictat de moviments|El dictado de movimientos', timer: 8, punts: ["La goma comença a l'origen (0, 0).|La goma empieza en el origen (0, 0).", 'Llegiu tres targetes i calculeu on quedarà.|Leed tres tarjetas y calculad dónde quedará.', 'Moveu-la amb el regle i comproveu-ho.|Movedla con la regla y comprobadlo.'], nota: 'Per parelles. Canvien els papers a cada ronda.|Por parejas. Cambian los papeles en cada ronda.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Porta el cub al fantasma.|Lleva el cubo al fantasma.', 'Mou tres peces 25 mm a la dreta.|Mueve tres piezas 25 mm a la derecha.', 'Posa els ulls al robot.|Pon los ojos al robot.', 'Centra la tapa.|Centra la tapa.'], nota: 'Recorda: la pestanya Posició és la de la precisió.|Recuerda: la pestaña Posición es la de la precisión.' },
      { id: 's10', k: 'media', t: 'Els ulls del robot|Los ojos del robot', x: 'x = −8 i x = 8, y = −10, base a z = 10.|x = −8 y x = 8, y = −10, base en z = 10.', media: { k: 'model', model: { parts: CARA }, view: 'front' }, nota: "Per a qui s'encalli: els ulls sobresurten la meitat per davant de la cara; la y del centre és la cara de davant (−10).|Para quien se atasque: los ojos sobresalen la mitad por delante de la cara; la y del centro es la cara de delante (−10)." },
      { id: 's11', k: 'concepte', t: 'Primer arrossegar, després afinar|Primero arrastrar, después afinar', x: "Arrossegueu fins a prop del fantasma i, després, mireu els números de Posició i corregiu-los.|Arrastrad hasta cerca del fantasma y, después, mirad los números de Posición y corregidlos.", nota: 'Bona estratègia per a qui ho vol fer tot amb el dit.|Buena estrategia para quien lo quiere hacer todo con el dedo.' },
      { id: 's12', k: 'repte', t: 'La teva inicial|Tu inicial', punts: ['La primera lletra del teu nom.|La primera letra de tu nombre.', 'Almenys 3 peces que es toquin.|Al menos 3 piezas que se toquen.', 'Res solt i tot sobre la placa.|Nada suelto y todo sobre la placa.'], nota: "Si «una sola peça» no es marca, hi ha un espai entre dues peces: que mirin on s'acaba cada una.|Si «una sola pieza» no se marca, hay un espacio entre dos piezas: que miren dónde acaba cada una." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Arrossegar apropa; els números deixen la peça exacta.|Arrastrar acerca; los números dejan la pieza exacta.', 'La quadrícula salta de 10, 5 o 1 mm.|La cuadrícula salta de 10, 5 o 1 mm.', 'Moure és sumar o restar a la posició.|Mover es sumar o restar a la posición.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['x = 15 i 20 mm a l\'esquerra: on queda?|x = 15 y 20 mm a la izquierda: ¿dónde queda?', 'Quin salt fas servir per afinar?|¿Qué salto usas para afinar?'], nota: 'Respostes: x = −5 i el salt d\'1 mm.|Respuestas: x = −5 y el salto de 1 mm.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "On és el tresor? Amaga un punt en una quadrícula i dona tres moviments per trobar-lo.|¿Dónde está el tesoro? Esconde un punto en una cuadrícula y da tres movimientos para encontrarlo.", nota: 'Proposta opcional per compartir a la sessió següent.|Propuesta opcional para compartir en la sesión siguiente.' }
    ],
    print: [
      { id: 'p1', t: 'Targetes de moviments|Tarjetas de movimientos', k: 'targetes', intro: "Retalleu-les i barregeu-les. Cada parella en treu tres per ronda.|Recortadlas y mezcladlas. Cada pareja saca tres por ronda.",
        items: [{ t: '+30 en x|+30 en x', n: 1 }, { t: '−20 en x|−20 en x', n: 1 }, { t: '+15 en x|+15 en x', n: 1 }, { t: '−35 en x|−35 en x', n: 1 }, { t: '+20 en y|+20 en y', n: 1 }, { t: '−10 en y|−10 en y', n: 1 }, { t: '+25 en y|+25 en y', n: 1 }, { t: '−15 en y|−15 en y', n: 1 }] },
      { id: 'p2', t: 'Fitxa: on queda la peça?|Ficha: ¿dónde queda la pieza?', k: 'fitxa', intro: 'Calcula la posició nova. Dreta, fons i amunt sumen; esquerra, davant i avall resten.|Calcula la posición nueva. Derecha, fondo y arriba suman; izquierda, delante y abajo restan.',
        items: [{ q: 'Una peça és a x = 10. La mous 25 mm a la dreta. x = ____|Una pieza está en x = 10. La mueves 25 mm a la derecha. x = ____', sol: 'x = 35|x = 35' }, { q: "Una peça és a x = 10. La mous 25 mm a l'esquerra. x = ____|Una pieza está en x = 10. La mueves 25 mm a la izquierda. x = ____", sol: 'x = −15|x = −15' },
          { q: 'Una peça és a y = −20. La mous 30 mm cap al fons. y = ____|Una pieza está en y = −20. La mueves 30 mm hacia el fondo. y = ____', sol: 'y = 10|y = 10' }, { q: "Un cilindre de 12 mm d'alt és a terra. A quina z comença el que hi poses a sobre? z = ____|Un cilindro de 12 mm de alto está en el suelo. ¿En qué z empieza el que pones encima? z = ____", sol: 'z = 12|z = 12' }] }
    ]
  },
  /* ---------- Sessió 2 · Girar ---------- */
  'm3-2': {
    intro: "Segona sessió de la unitat: l'alumnat aprèn a girar peces. Primer en z, vist des de dalt, on el gir s'entén com en un rellotge; després en x i en y, que serveixen per tombar peces (les rodes i els braços del robot). Es treballen els angles de 15°, 45°, 90° i 180°, el sentit del gir (positiu o negatiu) i el fet que el gir es fa al voltant del centre de la peça. També descobreixen que algunes formes, com el cilindre dret, no canvien quan es giren en z.|Segunda sesión de la unidad: el alumnado aprende a girar piezas. Primero en z, visto desde arriba, donde el giro se entiende como en un reloj; después en x y en y, que sirven para tumbar piezas (las ruedas y los brazos del robot). Se trabajan los ángulos de 15°, 45°, 90° y 180°, el sentido del giro (positivo o negativo) y el hecho de que el giro se hace alrededor del centro de la pieza. También descubren que algunas formas, como el cilindro de pie, no cambian cuando se giran en z.",
    claus: ["Una peça gira al voltant del seu centre: les dues puntes es mouen alhora.|Una pieza gira alrededor de su centro: las dos puntas se mueven a la vez.", "90° és un quart de volta, 180° mitja volta i 45° la meitat de 90°; cada toc de + o − gira 15°.|90° es un cuarto de vuelta, 180° media vuelta y 45° la mitad de 90°; cada toque de + o − gira 15°.",
      "Des de dalt, un angle positiu gira al revés de les agulles del rellotge i un de negatiu, al contrari.|Desde arriba, un ángulo positivo gira al revés de las agujas del reloj y uno negativo, al contrario.", "Girar en z fa voltar la peça; girar 90° en x o en y la tomba (rodes, braços, troncs).|Girar en z hace dar vueltas a la pieza; girar 90° en x o en y la tumba (ruedas, brazos, troncos)."],
    prev: ["Moure peces amb números (sessió anterior).|Mover piezas con números (sesión anterior).", "Conèixer el rellotge d'agulles: quart, mitja i hora sencera.|Conocer el reloj de agujas: cuarto, media y hora entera.", "Saber que els eixos x, y i z tenen colors (vermell, verd i blau).|Saber que los ejes x, y y z tienen colores (rojo, verde y azul)."],
    obj: ["L'alumne/a gira una peça en z amb angles de 15°, 45°, 90° i 180° fent servir la pestanya Gir.|El alumno/a gira una pieza en z con ángulos de 15°, 45°, 90° y 180° usando la pestaña Giro.",
      "L'alumne/a relaciona l'angle amb la fracció de volta i amb el nombre de tocs de 15°.|El alumno/a relaciona el ángulo con la fracción de vuelta y con el número de toques de 15°.",
      "L'alumne/a tria el signe de l'angle segons el sentit en què vol girar.|El alumno/a elige el signo del ángulo según el sentido en que quiere girar.",
      "L'alumne/a tomba peces girant-les 90° en x o en y i les col·loca al lloc.|El alumno/a tumba piezas girándolas 90° en x o en y y las coloca en su sitio."],
    comp: ["Matemàtiques, sentit espacial: girs i orientació de figures en el pla i en l'espai|Matemáticas, sentido espacial: giros y orientación de figuras en el plano y en el espacio",
      "Matemàtiques, sentit de la mesura: l'angle i el grau; quart i mitja volta|Matemáticas, sentido de la medida: el ángulo y el grado; cuarto y media vuelta",
      "Matemàtiques, sentit numèric: múltiples de 15 i càlcul mental amb angles|Matemáticas, sentido numérico: múltiplos de 15 y cálculo mental con ángulos",
      "Tecnologia i digitalització: transformacions d'objectes en un programa de disseny 3D|Tecnología y digitalización: transformaciones de objetos en un programa de diseño 3D"],
    vocab: [['Girar|Girar', 'Fer voltar una peça al voltant del seu centre.|Hacer girar una pieza alrededor de su centro.'], ['Angle|Ángulo', "Quant gira una peça, mesurat en graus (°).|Cuánto gira una pieza, medido en grados (°)."], ['Grau (°)|Grado (°)', 'Una volta sencera té 360 graus.|Una vuelta entera tiene 360 grados.'],
      ['Quart de volta|Cuarto de vuelta', "Un gir de 90°, com la cantonada d'un full.|Un giro de 90°, como la esquina de una hoja."], ['Sentit del gir|Sentido del giro', 'Cap a quin costat gira: positiu (al revés del rellotge) o negatiu.|Hacia qué lado gira: positivo (al revés del reloj) o negativo.'], ['Tombar|Tumbar', "Girar una peça 90° en x o en y perquè quedi ajaguda.|Girar una pieza 90° en x o en y para que quede tumbada."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Girar»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Girar»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "Per alumne/a: una tira de paper de 10 cm, un llapis i un transportador o la fitxa del cercle d'angles|Por alumno/a: una tira de papel de 10 cm, un lápiz y un transportador o la ficha del círculo de ángulos"],
      imprimir: ["Targetes d'angles|Tarjetas de ángulos", 'Fitxa: quants graus?|Ficha: ¿cuántos grados?'],
      prep: ["Retallar tires de paper i imprimir les targetes d'angles (una per parella).|Recortar tiras de papel e imprimir las tarjetas de ángulos (una por pareja).", "Dibuixar a la pissarra un cercle amb línies cada 45° (0°, 45°, 90°…).|Dibujar en la pizarra un círculo con líneas cada 45° (0°, 45°, 90°…).", "Provar el repte de les rodes: cal girar en y, no en z.|Probar el reto de las ruedas: hay que girar en y, no en z."] },
    plan: [
      { min: 5, t: 'Braços i rodes|Brazos y ruedas', fase: 'inici', fa: "Recorda l'encàrrec del robot i mostra que totes les peces surten dretes. Pregunta com es podrien posar les rodes de costat. Connecta amb el rellotge: quant gira l'agulla en un quart d'hora?|Recuerda el encargo del robot y muestra que todas las piezas salen de pie. Pregunta cómo se podrían poner las ruedas de lado. Conecta con el reloj: ¿cuánto gira la aguja en un cuarto de hora?",
        diu: ["Com posaríeu un cilindre ajagut, com un tronc?|¿Cómo pondríais un cilindro tumbado, como un tronco?", "Quantes vegades cal girar un quart de volta per fer una volta sencera?|¿Cuántas veces hay que girar un cuarto de vuelta para dar una vuelta entera?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Angles i sentits|Ángulos y sentidos', fase: 'teoria', fa: "Presenta el gir al voltant del centre (animació de la barra) i els angles més habituals amb els tocs de 15°. Explica el sentit: positiu, al revés de les agulles del rellotge vist des de dalt. Acaba amb els girs en x i en y per tombar peces i amb el cas del cilindre dret, que no sembla girar en z.|Presenta el giro alrededor del centro (animación de la barra) y los ángulos más habituales con los toques de 15°. Explica el sentido: positivo, al revés de las agujas del reloj visto desde arriba. Acaba con los giros en x y en y para tumbar piezas y con el caso del cilindro de pie, que no parece girar en z.",
        diu: ["Quants tocs de 15° fan 45°? I 90°?|¿Cuántos toques de 15° hacen 45°? ¿Y 90°?", "Si gira cap al costat que no vull, què canvio?|Si gira hacia el lado que no quiero, ¿qué cambio?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'El rellotge de paper|El reloj de papel', fase: 'desconnectat', fa: "Cada alumne/a clava una tira de paper pel mig sobre el cercle d'angles i la gira 15°, 45°, 90° i −45°. Després, per parelles, un treu una targeta d'angle i l'altre el fa amb la tira; el company comprova amb el cercle.|Cada alumno/a clava una tira de papel por el medio sobre el círculo de ángulos y la gira 15°, 45°, 90° y −45°. Después, por parejas, uno saca una tarjeta de ángulo y el otro lo hace con la tira; el compañero comprueba con el círculo.",
        diu: ['Fixeu-vos: les dues puntes de la tira es mouen alhora.|Fijaos: las dos puntas de la tira se mueven a la vez.', 'Cap a quin costat va un angle negatiu?|¿Hacia qué lado va un ángulo negativo?'], slides: ['s8'], app: 'Encara no: activitat a la taula.|Todavía no: actividad en la mesa.', org: 'Per parelles|Por parejas' },
      { min: 20, t: "A l'ordinador: creus, rampes i rodes|En el ordenador: cruces, rampas y ruedas", fase: 'ordinador', fa: "Fan la sessió a l'app. A la creu i a la X n'hi ha prou amb el gir en z; a la rampa han de pensar quina és la part alta; a les rodes han de girar en y. Passa per les taules al repte de les rodes: és on més s'equivoquen d'eix.|Hacen la sesión en la app. En la cruz y en la X basta con el giro en z; en la rampa tienen que pensar cuál es la parte alta; en las ruedas tienen que girar en y. Pasa por las mesas en el reto de las ruedas: es donde más se equivocan de eje.",
        diu: ["Quin eix has de fer servir per tombar-la?|¿Qué eje tienes que usar para tumbarla?", "Mira-ho des de dalt: cap a on apunta ara?|Míralo desde arriba: ¿hacia dónde apunta ahora?"], slides: ['s9', 's10', 's11'], app: 'Sessió «Girar», fins a «La rosa dels vents».|Sesión «Girar», hasta «La rosa de los vientos».', org: 'Individual|Individual' },
      { min: 8, t: 'La rosa dels vents|La rosa de los vientos', fase: 'crea', fa: "Construeixen una estrella amb barres que es creuen al mateix centre, cada una amb un angle diferent. Com que giren al voltant del centre, totes queden centrades. Es desa al portafoli.|Construyen una estrella con barras que se cruzan en el mismo centro, cada una con un ángulo distinto. Como giran alrededor del centro, todas quedan centradas. Se guarda en el portafolio.",
        diu: ['Quins angles has fet servir? Quants graus hi ha entre una barra i la següent?|¿Qué ángulos has usado? ¿Cuántos grados hay entre una barra y la siguiente?'], slides: ['s12'], app: 'Pas «La rosa dels vents».|Paso «La rosa de los vientos».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa els angles i els eixos per tombar. Tiquet de sortida amb el cos: un quart de volta, mitja volta.|Repasa los ángulos y los ejes para tumbar. Ticket de salida con el cuerpo: un cuarto de vuelta, media vuelta.',
        diu: ['Ensenyeu-me amb el braç un gir de 90°. I de 45°?|Enseñadme con el brazo un giro de 90°. ¿Y de 45°?'], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Gira un cilindre dret en z i creu que el gir no funciona.|Gira un cilindro de pie en z y cree que el giro no funciona.", "Explica-li que el cilindre és igual per tots els costats; per tombar-lo ha de girar en x o en y. Que ho provi amb una barra (caixa allargada) per veure el gir en z.|Explícale que el cilindro es igual por todos los lados; para tumbarlo tiene que girar en x o en y. Que lo pruebe con una barra (caja alargada) para ver el giro en z."],
      ["Fa 9 tocs per arribar a 90° (compta de 10 en 10).|Hace 9 toques para llegar a 90° (cuenta de 10 en 10).", "Recorda-li que cada toc són 15°: 15, 30, 45, 60, 75, 90. O que escrigui el número directament.|Recuérdale que cada toque son 15°: 15, 30, 45, 60, 75, 90. O que escriba el número directamente."],
      ["La rampa li queda baixant cap a la plataforma.|La rampa le queda bajando hacia la plataforma.", "Que la miri de costat: la part alta ha de tocar la plataforma. Mitja volta (180°) la gira de l'altra banda.|Que la mire de lado: la parte alta tiene que tocar la plataforma. Media vuelta (180°) la gira del otro lado."],
      ["Després de girar, la peça s'ha desplaçat i no sap per què.|Después de girar, la pieza se ha desplazado y no sabe por qué.", "El taller manté la base a terra quan gires; mira de nou els números de Posició i corregeix x, y i z si cal.|El taller mantiene la base en el suelo cuando giras; mira de nuevo los números de Posición y corrige x, y y z si hace falta."]],
    diff: { mes: "Fer el rellotge de la plaça i un segon rellotge que marqui les 9 (angle negatiu). A la rosa dels vents, fer 8 barres separades 22,5° o 6 barres separades 30°.|Hacer el reloj de la plaza y un segundo reloj que marque las 9 (ángulo negativo). En la rosa de los vientos, hacer 8 barras separadas 22,5° o 6 barras separadas 30°.",
      menys: "Treballar només angles de 90° i 180° amb la vista de dalt fixa. Tenir a la taula el cercle d'angles amb els tocs de 15° comptats.|Trabajar solo ángulos de 90° y 180° con la vista de arriba fija. Tener en la mesa el círculo de ángulos con los toques de 15° contados." },
    aval: { ticket: ['Quants tocs de 15° calen per girar 90°?|¿Cuántos toques de 15° hacen falta para girar 90°?', 'Per tombar un cilindre, en quin eix el gires?|Para tumbar un cilindro, ¿en qué eje lo giras?'],
      rubric: [['Angles|Ángulos', 'Gira la peça l\'angle exacte (15°, 45°, 90°, 180°) i ho relaciona amb la fracció de volta.|Gira la pieza el ángulo exacto (15°, 45°, 90°, 180°) y lo relaciona con la fracción de vuelta.', 'Arriba a l\'angle a base de provar, sense saber quants tocs calen.|Llega al ángulo a base de probar, sin saber cuántos toques hacen falta.'],
        ['Sentit|Sentido', 'Tria el signe correcte per girar cap a un costat o l\'altre.|Elige el signo correcto para girar hacia un lado u otro.', "Confon el sentit i ho corregeix després de mirar-ho.|Confunde el sentido y lo corrige después de mirarlo."],
        ['Tombar peces|Tumbar piezas', 'Tria l\'eix correcte (x o y) per tombar una peça i la col·loca bé.|Elige el eje correcto (x o y) para tumbar una pieza y la coloca bien.', 'Prova els tres eixos fins que encerta.|Prueba los tres ejes hasta que acierta.']] },
    casa: "Busca a casa coses que giren: el pom de la porta, l'agulla del rellotge, una aixeta. Quant giren? Un quart de volta, mitja volta…?|Busca en casa cosas que giren: el pomo de la puerta, la aguja del reloj, un grifo. ¿Cuánto giran? ¿Un cuarto de vuelta, media vuelta…?",
    faq: [['Per què un angle positiu gira al revés de les agulles del rellotge?|¿Por qué un ángulo positivo gira al revés de las agujas del reloj?', "És el conveni de les matemàtiques i dels programes de disseny: si mires des de dalt, l'eix x es gira cap a l'eix y. Els rellotges van al revés per tradició.|Es la convención de las matemáticas y de los programas de diseño: si miras desde arriba, el eje x gira hacia el eje y. Los relojes van al revés por tradición."],
      ['És el mateix girar 180° que −180°?|¿Es lo mismo girar 180° que −180°?', 'Sí: mitja volta cap a un costat o cap a l\'altre deixa la peça igual.|Sí: media vuelta hacia un lado o hacia el otro deja la pieza igual.'],
      ["Per què la peça es desplaça quan la tombo?|¿Por qué la pieza se desplaza cuando la tumbo?", "Gira al voltant del seu centre i després el taller la baixa perquè la base continuï tocant la placa. Per això cal revisar la posició després de tombar-la.|Gira alrededor de su centro y después el taller la baja para que la base siga tocando la placa. Por eso hay que revisar la posición después de tumbarla."]],
    tec: [["Els botons + i − del gir no fan res.|Los botones + y − del giro no hacen nada.", "Cal tenir una peça triada i la pestanya Gir oberta. Si hi ha diverses peces triades, giren totes juntes al voltant del centre del grup.|Hay que tener una pieza seleccionada y la pestaña Giro abierta. Si hay varias piezas seleccionadas, giran todas juntas alrededor del centro del grupo."],
      ["En escriure 270 al camp, surt −90.|Al escribir 270 en el campo, sale −90.", "És correcte: 270° i −90° deixen la peça igual. El taller sempre mostra l'angle entre −180° i 180°.|Es correcto: 270° y −90° dejan la pieza igual. El taller siempre muestra el ángulo entre −180° y 180°."],
      ['No es veu bé si la barra està a 45°.|No se ve bien si la barra está a 45°.', 'Feu servir la vista de dalt (planta): els girs en z es veuen sense deformar.|Usad la vista de arriba (planta): los giros en z se ven sin deformar.']],
    extra: ["Fer una rellotgeria: diversos rellotges que marquin hores en punt diferents (cada hora són 30°).|Hacer una relojería: varios relojes que marquen horas en punto diferentes (cada hora son 30°).", 'Buscar angles de 45° i 90° a l\'aula: cantonades, escaires, diagonals de rajoles.|Buscar ángulos de 45° y 90° en el aula: esquinas, escuadras, diagonales de baldosas.', "Inventar una «dansa dels angles» amb girs de 45°, 90° i 180° per a la pausa activa.|Inventar una «danza de los ángulos» con giros de 45°, 90° y 180° para la pausa activa."],
    trans: ["Sessió següent: escalar peces (el doble i la meitat) sense deformar-les.|Sesión siguiente: escalar piezas (el doble y la mitad) sin deformarlas.", "Matemàtiques: l'angle, el grau i les fraccions de volta.|Matemáticas: el ángulo, el grado y las fracciones de vuelta."],
    slides: [
      { id: 's1', k: 'portada', t: 'Girar|Girar', x: '15°, 45°, 90°… i peces tombades|15°, 45°, 90°… y piezas tumbadas', nota: "Recorda la fitxa del robot: braços estirats i rodes de costat.|Recuerda la ficha del robot: brazos estirados y ruedas de lado." },
      { id: 's2', k: 'pregunta', t: "Quant gira l'agulla en un quart d'hora?|¿Cuánto gira la aguja en un cuarto de hora?", x: "I en mitja hora? I en una hora?|¿Y en media hora? ¿Y en una hora?", nota: 'Un quart, mitja i una volta: 90°, 180° i 360°.|Un cuarto, media y una vuelta: 90°, 180° y 360°.' },
      { id: 's3', k: 'anim', t: 'Girar al voltant del centre|Girar alrededor del centro', anim: 'm32gir', x: 'Les dues puntes es mouen alhora; el centre es queda quiet.|Las dos puntas se mueven a la vez; el centro se queda quieto.', nota: "Compara-ho amb una porta giratòria o les aspes d'un molí.|Compáralo con una puerta giratoria o las aspas de un molino." },
      { id: 's4', k: 'anim', t: 'Els angles|Los ángulos', anim: 'm32ang', x: 'Cada toc de + o − són 15°.|Cada toque de + o − son 15°.', nota: 'Feu el càlcul junts: 3 tocs, 45°; 6 tocs, 90°; 12 tocs, 180°.|Haced el cálculo juntos: 3 toques, 45°; 6 toques, 90°; 12 toques, 180°.' },
      { id: 's5', k: 'media', t: 'Positiu o negatiu|Positivo o negativo', x: 'Blava: +30°. Taronja: −30°.|Azul: +30°. Naranja: −30°.', media: { k: 'model', model: { parts: [B('p', 'box', [44, 8, 8], -28, 0, 0, '#3D7BF4', { r: [0, 0, 30] }), B('n', 'box', [44, 8, 8], 28, 0, 0, '#FF8A3D', { r: [0, 0, -30] })] }, view: 'top' }, nota: "Vist des de dalt, el positiu va al revés de les agulles del rellotge.|Visto desde arriba, el positivo va al revés de las agujas del reloj." },
      { id: 's6', k: 'anim', t: 'Girar en x, y o z|Girar en x, y o z', anim: 'm32eix', x: 'En z, gira com una baldufa; en x o en y, es tomba.|En z, gira como una peonza; en x o en y, se tumba.', nota: 'Associa cada eix al seu color i a la direcció en què queda la peça ajaguda.|Asocia cada eje a su color y a la dirección en que queda la pieza tumbada.' },
      { id: 's7', k: 'media', t: 'Cilindres dret i tombats|Cilindros de pie y tumbados', x: 'Blau: dret. Verd: 90° en x. Taronja: 90° en y.|Azul: de pie. Verde: 90° en x. Naranja: 90° en y.', media: { k: 'model', model: { parts: [B('d', 'cyl', [14, 14, 36], -30, 0, 0, '#3D7BF4'), B('x', 'cyl', [14, 14, 36], 0, 0, 0, '#2FB36D', { r: [90, 0, 0], h: 14 }), B('y', 'cyl', [14, 14, 36], 32, 0, 0, '#FF8A3D', { r: [0, 90, 0], h: 14 })] } }, nota: "Pregunta: si giro el blau en z, canviarà? (No: és igual per tots els costats.)|Pregunta: si giro el azul en z, ¿cambiará? (No: es igual por todos los lados.)" },
      { id: 's8', k: 'activitat', t: 'El rellotge de paper|El reloj de papel', timer: 8, punts: ['Clava la tira pel mig sobre el cercle.|Clava la tira por el medio sobre el círculo.', 'Gira-la 15°, 45°, 90° i −45°.|Gírala 15°, 45°, 90° y −45°.', 'En parella: un diu l\'angle i l\'altre el fa.|En pareja: uno dice el ángulo y el otro lo hace.'], nota: "Comproveu el sentit: positiu, al revés de les agulles del rellotge.|Comprobad el sentido: positivo, al revés de las agujas del reloj." },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['La creu i la X.|La cruz y la X.', 'La rampa que puja.|La rampa que sube.', 'Les rodes del carro.|Las ruedas del carro.'], nota: 'A les rodes, recordeu: es tomben girant en y.|En las ruedas, recordad: se tumban girando en y.' },
      { id: 's10', k: 'media', t: 'La rampa|La rampa', x: 'Mitja volta (180°) i la part alta toca la plataforma.|Media vuelta (180°) y la parte alta toca la plataforma.', media: { k: 'model', model: { parts: [B('plat', 'box', [30, 30, 20], 25, 0, 0, '#9AA3B5'), B('rampa', 'wedge', [30, 30, 20], -5, 0, 0, '#F5893A', { r: [0, 0, 180] })] } }, nota: "Per a qui s'encalli: mireu-la des del costat abans i després de girar-la.|Para quien se atasque: miradla desde el lado antes y después de girarla." },
      { id: 's11', k: 'media', t: 'El carro amb rodes|El carro con ruedas', x: 'Rodes: 90° en y, a x = −18 i x = 18.|Ruedas: 90° en y, en x = −18 y x = 18.', media: { k: 'model', model: { parts: [B('carro', 'box', [30, 30, 10], 0, 0, 8, '#E8453C'), roda('w1', -18), roda('w2', 18)] } }, nota: 'Les rodes queden de costat i toquen el carro.|Las ruedas quedan de lado y tocan el carro.' },
      { id: 's12', k: 'repte', t: 'La rosa dels vents|La rosa de los vientos', punts: ['Almenys 3 barres al mateix centre.|Al menos 3 barras en el mismo centro.', 'Cada barra amb un angle diferent.|Cada barra con un ángulo distinto.', 'Pinta-la de colors.|Píntala de colores.'], nota: 'Suggereix 0°, 45°, 90° i −45°, o 0°, 60° i 120°.|Sugiere 0°, 45°, 90° y −45°, o 0°, 60° y 120°.' },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Una peça gira al voltant del seu centre.|Una pieza gira alrededor de su centro.', '90° és un quart de volta; cada toc, 15°.|90° es un cuarto de vuelta; cada toque, 15°.', 'Per tombar, es gira en x o en y.|Para tumbar, se gira en x o en y.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Quants tocs de 15° fan 90°?|¿Cuántos toques de 15° hacen 90°?', 'En quin eix tombes un cilindre?|¿En qué eje tumbas un cilindro?'], nota: 'Respostes: 6 tocs; en x o en y.|Respuestas: 6 toques; en x o en y.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: 'Busca coses que giren a casa i digues quant giren.|Busca cosas que giren en casa y di cuánto giran.', nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [
      { id: 'p1', t: "Targetes d'angles|Tarjetas de ángulos", k: 'targetes', intro: "Retalleu-les. Una persona en treu una i l'altra fa el gir amb la tira de paper.|Recortadlas. Una persona saca una y la otra hace el giro con la tira de papel.",
        items: [{ t: '15°|15°', n: 1 }, { t: '30°|30°', n: 1 }, { t: '45°|45°', n: 1 }, { t: '90°|90°', n: 1 }, { t: '180°|180°', n: 1 }, { t: '−45°|−45°', n: 1 }, { t: '−90°|−90°', n: 1 }, { t: '135°|135°', n: 1 }] },
      { id: 'p2', t: 'Fitxa: quants graus?|Ficha: ¿cuántos grados?', k: 'fitxa', intro: 'Respon. Cada toc de + o − de la pestanya Gir són 15°.|Responde. Cada toque de + o − de la pestaña Giro son 15°.',
        items: [{ q: 'Quants graus són un quart de volta? ____ °|¿Cuántos grados son un cuarto de vuelta? ____ °', sol: '90°|90°' }, { q: 'Quants tocs de 15° calen per girar 45°? ____|¿Cuántos toques de 15° hacen falta para girar 45°? ____', sol: '3 tocs|3 toques' },
          { q: "Una barra està a 30°. Quant més l'has de girar perquè quedi a 90°? ____ °|Una barra está a 30°. ¿Cuánto más tienes que girarla para que quede a 90°? ____ °", sol: '60°|60°' }, { q: 'Vols tombar un cilindre perquè quedi al llarg de l\'eix x. En quin eix el gires? ____|Quieres tumbar un cilindro para que quede a lo largo del eje x. ¿En qué eje lo giras? ____', sol: 'En y (90°)|En y (90°)' }] }
    ]
  },
  /* ---------- Sessió 3 · Més gran, més petit ---------- */
  'm3-3': {
    intro: "Tercera sessió de la unitat: l'escalat. L'alumnat descobreix la diferència entre canviar una sola mida (la peça s'estira i es deforma) i canviar-les totes alhora amb el botó Proporcional (la peça creix sense deformar-se). Es treballen el doble (2:1) i la meitat (1:2), i el pas més important: quan una figura té diverses peces, en escalar-la també s'han de multiplicar les alçades on comença cada peça. Com a curiositat, es mostra que el doble ocupa vuit vegades més volum.|Tercera sesión de la unidad: el escalado. El alumnado descubre la diferencia entre cambiar una sola medida (la pieza se estira y se deforma) y cambiarlas todas a la vez con el botón Proporcional (la pieza crece sin deformarse). Se trabajan el doble (2:1) y la mitad (1:2), y el paso más importante: cuando una figura tiene varias piezas, al escalarla también se tienen que multiplicar las alturas donde empieza cada pieza. Como curiosidad, se muestra que el doble ocupa ocho veces más volumen.",
    claus: ["Canviar una sola mida estira la peça; canviar-les totes en la mateixa proporció la fa créixer sense deformar-la.|Cambiar una sola medida estira la pieza; cambiarlas todas en la misma proporción la hace crecer sin deformarla.", "El doble (2:1) és multiplicar cada mida per 2; la meitat (1:2), dividir-la entre 2.|El doble (2:1) es multiplicar cada medida por 2; la mitad (1:2), dividirla entre 2.",
      "En una figura de diverses peces, també s'escalen les alçades i les distàncies on va cada peça.|En una figura de varias piezas, también se escalan las alturas y las distancias donde va cada pieza.", "El doble de cada mida ocupa 8 vegades més: més plàstic i més temps d'impressió.|El doble de cada medida ocupa 8 veces más: más plástico y más tiempo de impresión."],
    prev: ['Moure i girar peces amb números (sessions anteriors).|Mover y girar piezas con números (sesiones anteriores).', 'Multiplicar i dividir per 2.|Multiplicar y dividir por 2.', 'Saber que la z de la base és on comença una peça.|Saber que la z de la base es donde empieza una pieza.'],
    obj: ["L'alumne/a canvia una mida d'una peça per estirar-la fins a unes mides donades.|El alumno/a cambia una medida de una pieza para estirarla hasta unas medidas dadas.",
      "L'alumne/a fa servir Proporcional per fer una peça el doble o la meitat sense deformar-la.|El alumno/a usa Proporcional para hacer una pieza el doble o la mitad sin deformarla.",
      "L'alumne/a escala una figura de dues peces a 2:1 multiplicant també les alçades.|El alumno/a escala una figura de dos piezas a 2:1 multiplicando también las alturas.",
      "L'alumne/a reconeix quan una figura escalada està deformada o mal recolzada.|El alumno/a reconoce cuándo una figura escalada está deformada o mal apoyada."],
    comp: ["Matemàtiques, sentit de la mesura: proporcionalitat i escales (2:1, 1:2)|Matemáticas, sentido de la medida: proporcionalidad y escalas (2:1, 1:2)", "Matemàtiques, sentit numèric: doble, meitat i multiplicació|Matemáticas, sentido numérico: doble, mitad y multiplicación",
      "Matemàtiques, sentit espacial: figures semblants i volum (curiositat del 2 × 2 × 2)|Matemáticas, sentido espacial: figuras semejantes y volumen (curiosidad del 2 × 2 × 2)", "Tecnologia i digitalització: maquetes i models a escala|Tecnología y digitalización: maquetas y modelos a escala"],
    vocab: [['Escalar|Escalar', "Fer una peça o una figura més gran o més petita.|Hacer una pieza o una figura más grande o más pequeña."], ['Proporcional|Proporcional', 'Totes les mides canvien igual: la forma no es deforma.|Todas las medidas cambian igual: la forma no se deforma.'], ['Escala 2:1|Escala 2:1', 'El doble: cada mida es multiplica per 2.|El doble: cada medida se multiplica por 2.'],
      ['Escala 1:2|Escala 1:2', 'La meitat: cada mida es divideix entre 2.|La mitad: cada medida se divide entre 2.'], ['Deformar|Deformar', "Canviar la forma d'una peça perquè les mides no han canviat igual.|Cambiar la forma de una pieza porque las medidas no han cambiado igual."], ['Maqueta|Maqueta', "Un model d'un objecte real fet a escala.|Un modelo de un objeto real hecho a escala."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Més gran, més petit»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Más grande, más pequeño»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Paper quadriculat (quadrets de 5 mm) i llapis de colors|Papel cuadriculado (cuadritos de 5 mm) y lápices de colores', "Opcional: 8 daus o cubets iguals per muntar el «doble» d'un cub|Opcional: 8 dados o cubitos iguales para montar el «doble» de un cubo"],
      imprimir: ['Fitxa: dibuixa al doble|Ficha: dibuja al doble'], prep: ["Dibuixar a la pissarra un robot senzill en una quadrícula (cos de 4 × 3 quadrets, cap de 2 × 2).|Dibujar en la pizarra un robot sencillo en una cuadrícula (cuerpo de 4 × 3 cuadritos, cabeza de 2 × 2).", "Si en teniu, preparar 8 cubets per mostrar que el doble d'un cub n'ocupa 8.|Si tenéis, preparar 8 cubitos para mostrar que el doble de un cubo ocupa 8.", "Provar el repte de l'arbre al doble: cal canviar quatre mides i dues posicions.|Probar el reto del árbol al doble: hay que cambiar cuatro medidas y dos posiciones."] },
    plan: [
      { min: 5, t: 'Al doble i a la meitat|Al doble y a la mitad', fase: 'inici', fa: "Explica la nova petició de l'escola: un robot el doble de gran i robotets de la meitat. Pregunta què vol dir «el doble» i si n'hi ha prou de fer-lo el doble d'alt.|Explica la nueva petición de la escuela: un robot el doble de grande y robotitos de la mitad. Pregunta qué quiere decir «el doble» y si basta con hacerlo el doble de alto.",
        diu: ["Si faig un cub el doble d'alt però igual d'ample, continua sent un cub?|Si hago un cubo el doble de alto pero igual de ancho, ¿sigue siendo un cubo?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Estirar o escalar|Estirar o escalar', fase: 'teoria', fa: "Mostra primer què passa quan canvies una sola mida (la peça s'estira) i després el cadenat Proporcional. Defineix 2:1 i 1:2 amb els tres cubs. Fes la curiositat dels 8 cubets amb material si en teniu. Acaba amb l'arbre: per què s'ha de doblar també l'alçada on comença la copa.|Muestra primero qué pasa cuando cambias una sola medida (la pieza se estira) y después el candado Proporcional. Define 2:1 y 1:2 con los tres cubos. Haz la curiosidad de los 8 cubitos con material si tenéis. Acaba con el árbol: por qué hay que doblar también la altura donde empieza la copa.",
        diu: ['Un cub de 20 mm al doble: quines mides té?|Un cubo de 20 mm al doble: ¿qué medidas tiene?', 'Si la copa començava a z = 10, on comença al doble?|Si la copa empezaba en z = 10, ¿dónde empieza al doble?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Dibuixa al doble|Dibuja al doble', fase: 'desconnectat', fa: "Cada alumne/a copia el robot de la fitxa a la quadrícula gran, al doble: cada quadret es converteix en dos. Primer compten quadrets de cada part i ho apunten. Els que acaben, el dibuixen a la meitat.|Cada alumno/a copia el robot de la ficha en la cuadrícula grande, al doble: cada cuadrito se convierte en dos. Primero cuentan cuadritos de cada parte y lo apuntan. Quienes acaban, lo dibujan a la mitad.",
        diu: ['On comença el cap al dibuix gran? Compteu des de baix.|¿Dónde empieza la cabeza en el dibujo grande? Contad desde abajo.', "Té la mateixa forma? Com ho sabeu?|¿Tiene la misma forma? ¿Cómo lo sabéis?"], slides: ['s8'], app: 'Encara no: fitxa i llapis.|Todavía no: ficha y lápiz.', org: 'Individual|Individual' },
      { min: 20, t: "A l'ordinador: estira, dobla i redueix|En el ordenador: estira, dobla y reduce", fase: 'ordinador', fa: "Fan la sessió a l'app. El tauler es fa sense el cadenat; el cub gegant i la bola, amb el cadenat. A l'arbre al doble, passa per les taules: és el repte que més costa perquè cal recolzar la copa a z = 20.|Hacen la sesión en la app. El tablero se hace sin el candado; el cubo gigante y la bola, con el candado. En el árbol al doble, pasa por las mesas: es el reto que más cuesta porque hay que apoyar la copa en z = 20.",
        diu: ['Has d\'estirar o escalar? Cal el cadenat?|¿Tienes que estirar o escalar? ¿Hace falta el candado?', "On s'acaba el tronc nou?|¿Dónde acaba el tronco nuevo?"], slides: ['s9', 's10', 's11'], app: 'Sessió «Més gran, més petit», fins a «Robot i robot gegant».|Sesión «Más grande, más pequeño», hasta «Robot y robot gigante».', org: 'Individual|Individual' },
      { min: 8, t: 'Robot i robot gegant|Robot y robot gigante', fase: 'crea', fa: "Fan un robot petit de dues o tres peces i, al costat, el mateix robot al doble. Poden comprovar la forma mirant-los des de davant. Es desa al portafoli.|Hacen un robot pequeño de dos o tres piezas y, al lado, el mismo robot al doble. Pueden comprobar la forma mirándolos desde delante. Se guarda en el portafolio.",
        diu: ['Has doblat també on comença el cap?|¿Has doblado también dónde empieza la cabeza?'], slides: ['s12'], app: 'Pas «Robot i robot gegant».|Paso «Robot y robot gigante».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa la diferència entre estirar i escalar, i el 2:1 i 1:2. Tiquet de sortida.|Repasa la diferencia entre estirar y escalar, y el 2:1 y 1:2. Ticket de salida.',
        diu: ["Digueu-me una cosa que sigui una maqueta a escala.|Decidme una cosa que sea una maqueta a escala."], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Per fer el doble, només canvia una mida (l'alçada).|Para hacer el doble, solo cambia una medida (la altura).", "Posa-li al costat el cub original i el que ha fet: és igual d'ample? Que activi el cadenat i ho torni a provar.|Ponle al lado el cubo original y el que ha hecho: ¿es igual de ancho? Que active el candado y vuelva a probar."],
      ["Suma en lloc de multiplicar: el doble de 20 li surt 22 o 40 només en una mida.|Suma en lugar de multiplicar: el doble de 20 le sale 22 o 40 solo en una medida.", 'Recorda que el doble és «dues vegades»: 20 + 20 = 40, a cada mida.|Recuerda que el doble es «dos veces»: 20 + 20 = 40, en cada medida.'],
      ["A l'arbre al doble, la copa queda enfonsada dins del tronc.|En el árbol al doble, la copa queda hundida dentro del tronco.", "Pregunta-li on s'acaba el tronc nou (20 mm): allà ha de començar la copa. Que ho miri des del costat.|Pregúntale dónde acaba el tronco nuevo (20 mm): ahí tiene que empezar la copa. Que lo mire desde el lado."],
      ["Deixa el cadenat activat quan només ha de canviar una mida.|Deja el candado activado cuando solo tiene que cambiar una medida.", "Si totes les mides canvien quan no vol, que miri si el cadenat està encès i el desactivi.|Si todas las medidas cambian cuando no quiere, que mire si el candado está encendido y lo desactive."]],
    diff: { mes: "Fer l'arbre a la meitat (1:2) a més del doble i comparar les tres mides. Calcular quant plàstic gasta el cub de 40 mm respecte del de 20 mm (8 vegades més).|Hacer el árbol a la mitad (1:2) además del doble y comparar los tres tamaños. Calcular cuánto plástico gasta el cubo de 40 mm respecto al de 20 mm (8 veces más).",
      menys: 'Treballar primer només amb el cadenat i peces soles. Per a l\'arbre, donar les quatre mides noves escrites en un paper.|Trabajar primero solo con el candado y piezas solas. Para el árbol, dar las cuatro medidas nuevas escritas en un papel.' },
    aval: { ticket: ['Una caixa fa 10 × 20 × 30 mm. Com és al doble?|Una caja mide 10 × 20 × 30 mm. ¿Cómo es al doble?', 'Per a què serveix el botó Proporcional?|¿Para qué sirve el botón Proporcional?'],
      rubric: [['Estirar i escalar|Estirar y escalar', 'Distingeix quan cal canviar una mida i quan totes, i fa servir el cadenat.|Distingue cuándo hay que cambiar una medida y cuándo todas, y usa el candado.', 'Fa servir sempre el mateix mètode i la peça es deforma.|Usa siempre el mismo método y la pieza se deforma.'],
        ['Doble i meitat|Doble y mitad', 'Calcula les mides a 2:1 i a 1:2 sense errors.|Calcula las medidas a 2:1 y a 1:2 sin errores.', "S'equivoca en alguna mida o suma en lloc de multiplicar.|Se equivoca en alguna medida o suma en lugar de multiplicar."],
        ['Figures escalades|Figuras escaladas', 'Escala la figura i també les alçades: tot queda ben recolzat.|Escala la figura y también las alturas: todo queda bien apoyado.', "Escala les peces però les deixa enfonsades o flotant.|Escala las piezas pero las deja hundidas o flotando."]] },
    casa: "Busca a casa una cosa i la seva versió en petit o en gran (un cotxe en miniatura i un de veritat, una foto petita i una ampliada). Quantes vegades més gran és?|Busca en casa una cosa y su versión en pequeño o en grande (un coche en miniatura y uno de verdad, una foto pequeña y una ampliada). ¿Cuántas veces más grande es?",
    faq: [["Per què la bola continua tocant a terra quan la faig més petita?|¿Por qué la bola sigue tocando el suelo cuando la hago más pequeña?", "Perquè quan canvies una mida el taller manté la base a la mateixa alçada. Per això, després d'escalar, cal tornar a col·locar la peça on va.|Porque cuando cambias una medida el taller mantiene la base a la misma altura. Por eso, después de escalar, hay que volver a colocar la pieza donde va."],
      ["Què vol dir una escala 1:100?|¿Qué quiere decir una escala 1:100?", "Que el model és 100 vegades més petit que l'objecte real: 1 cm de la maqueta són 100 cm (1 m) de veritat.|Que el modelo es 100 veces más pequeño que el objeto real: 1 cm de la maqueta son 100 cm (1 m) de verdad."],
      ['Per què el doble ocupa 8 vegades més i no 2?|¿Por qué el doble ocupa 8 veces más y no 2?', "Perquè es dobla en tres direccions: 2 vegades més ample, 2 més fondo i 2 més alt: 2 × 2 × 2 = 8. És una curiositat: no cal que ho dominin.|Porque se dobla en tres direcciones: 2 veces más ancho, 2 más hondo y 2 más alto: 2 × 2 × 2 = 8. Es una curiosidad: no hace falta que lo dominen."]],
    tec: [["No trobo el botó Proporcional.|No encuentro el botón Proporcional.", "És a la pestanya Mida, sota els tres camps, amb el dibuix d'un cadenat. Cal tenir una sola peça triada.|Está en la pestaña Medida, debajo de los tres campos, con el dibujo de un candado. Hay que tener una sola pieza seleccionada."],
      ["Amb diverses peces triades no es poden canviar les mides.|Con varias piezas seleccionadas no se pueden cambiar las medidas.", "És així: les mides es canvien peça a peça. Per escalar una figura, es fa cada peça i després es recol·loquen.|Es así: las medidas se cambian pieza a pieza. Para escalar una figura, se hace cada pieza y después se recolocan."],
      ['El + i el − de la mida van de 5 en 5.|El + y el − de la medida van de 5 en 5.', 'Fan servir el salt de la quadrícula. Canvieu-lo a 1 mm o escriviu el número directament.|Usan el salto de la cuadrícula. Cambiadlo a 1 mm o escribid el número directamente.']],
    extra: ["Fer una família de tres ninots de neu: a 1:2, a 1:1 i a 2:1.|Hacer una familia de tres muñecos de nieve: a 1:2, a 1:1 y a 2:1.", 'Mesurar un objecte de l\'aula i calcular-ne les mides per fer-ne una maqueta a escala 1:10.|Medir un objeto del aula y calcular sus medidas para hacer una maqueta a escala 1:10.', "Muntar amb 8 i amb 27 cubets el doble i el triple d'un cub i comptar-los.|Montar con 8 y con 27 cubitos el doble y el triple de un cubo y contarlos."],
    trans: ['Sessió següent: el projecte del robot de peces amb una fitxa tècnica.|Sesión siguiente: el proyecto del robot de piezas con una ficha técnica.', 'Matemàtiques: proporcionalitat, doble i meitat.|Matemáticas: proporcionalidad, doble y mitad.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Més gran, més petit|Más grande, más pequeño', x: 'Al doble i a la meitat, sense deformar|Al doble y a la mitad, sin deformar', nota: "L'escola vol un robot gegant i robotets petits.|La escuela quiere un robot gigante y robotitos pequeños." },
      { id: 's2', k: 'pregunta', t: "Un cub el doble d'alt continua sent un cub?|¿Un cubo el doble de alto sigue siendo un cubo?", x: 'Què més s\'ha de doblar?|¿Qué más hay que doblar?', nota: "Busquem que diguin que s'ha de doblar l'amplada i la fondària també.|Buscamos que digan que hay que doblar la anchura y el fondo también." },
      { id: 's3', k: 'media', t: 'Estirar una peça|Estirar una pieza', x: 'Lila: 20 × 20 × 20. Blava: x = 50. Verda: z = 40.|Lila: 20 × 20 × 20. Azul: x = 50. Verde: z = 40.', media: { k: 'model', model: { parts: [B('a', 'box', [20, 20, 20], -40, 0, 0, '#7C5CFF'), B('b', 'box', [50, 20, 20], 0, 0, 0, '#3D7BF4'), B('c', 'box', [20, 20, 40], 40, 0, 0, '#2FB36D')] } }, nota: 'Canviar una sola mida estira la peça en aquella direcció.|Cambiar una sola medida estira la pieza en esa dirección.' },
      { id: 's4', k: 'anim', t: 'Proporcional|Proporcional', anim: 'm33esc', x: 'Amb el cadenat, totes les mides canvien igual.|Con el candado, todas las medidas cambian igual.', nota: "Pregunta quina de les dues continua sent un quadrat.|Pregunta cuál de las dos sigue siendo un cuadrado." },
      { id: 's5', k: 'media', t: '2:1 i 1:2|2:1 y 1:2', x: 'Groc 10 mm · taronja 20 mm · vermell 40 mm.|Amarillo 10 mm · naranja 20 mm · rojo 40 mm.', media: { k: 'model', model: { parts: [B('a', 'box', [10, 10, 10], -35, 0, 0, '#F7C531'), B('b', 'box', [20, 20, 20], -10, 0, 0, '#FF8A3D'), B('c', 'box', [40, 40, 40], 30, 0, 0, '#E8453C')] } }, nota: 'El taronja és el model; el groc, la meitat; el vermell, el doble.|El naranja es el modelo; el amarillo, la mitad; el rojo, el doble.' },
      { id: 's6', k: 'anim', t: 'El doble ocupa 8 vegades més|El doble ocupa 8 veces más', anim: 'm33dob', x: '2 × 2 × 2 = 8 cubs petits.|2 × 2 × 2 = 8 cubos pequeños.', nota: "Curiositat. Si teniu cubets, munteu-ho a la taula.|Curiosidad. Si tenéis cubitos, montadlo en la mesa." },
      { id: 's7', k: 'media', t: "L'arbre i el seu doble|El árbol y su doble", x: 'La copa comença a z = 10 i, al doble, a z = 20.|La copa empieza en z = 10 y, al doble, en z = 20.', media: { k: 'model', model: { parts: [...ARBRE(-30, 1, 'p'), ...ARBRE(15, 2, 'g')] } }, nota: "Clau de la sessió: també es doblen les alçades on comença cada peça.|Clave de la sesión: también se doblan las alturas donde empieza cada pieza." },
      { id: 's8', k: 'activitat', t: 'Dibuixa al doble|Dibuja al doble', timer: 8, punts: ['Compta els quadrets de cada part.|Cuenta los cuadritos de cada parte.', 'Dibuixa\'l al doble a la quadrícula gran.|Dibújalo al doble en la cuadrícula grande.', 'Repte: a la meitat.|Reto: a la mitad.'], nota: 'Individual. Que comparin el resultat amb el company.|Individual. Que comparen el resultado con el compañero.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['El tauler de la taula (estirar).|El tablero de la mesa (estirar).', 'El cub gegant i la bola a la meitat.|El cubo gigante y la bola a la mitad.', "L'arbre al doble.|El árbol al doble."], nota: 'Pregunta a cada repte: estirar o escalar?|Pregunta en cada reto: ¿estirar o escalar?' },
      { id: 's10', k: 'media', t: 'El ninot mal escalat|El muñeco mal escalado', x: "El cap s'ha quedat a z = 20: està enfonsat.|La cabeza se ha quedado en z = 20: está hundida.", media: { k: 'model', model: { parts: [B('n1', 'sph', [40, 40, 40], 0, 0, 0, '#F3F3EE'), B('n2', 'sph', [28, 28, 28], 0, 0, 20, '#F3F3EE')] }, view: 'front' }, nota: 'Exemple de l\'error més habitual. On hauria de començar el cap? (z = 40.)|Ejemplo del error más habitual. ¿Dónde tendría que empezar la cabeza? (z = 40.)' },
      { id: 's11', k: 'concepte', t: 'Escalar una figura: la recepta|Escalar una figura: la receta', x: "1) Multiplica cada mida. 2) Multiplica l'alçada on comença cada peça. 3) Comprova-ho des del costat.|1) Multiplica cada medida. 2) Multiplica la altura donde empieza cada pieza. 3) Compruébalo desde el lado.", nota: "Deixeu-la a la vista mentre fan l'arbre.|Dejadla a la vista mientras hacen el árbol." },
      { id: 's12', k: 'repte', t: 'Robot i robot gegant|Robot y robot gigante', punts: ['Un robot petit (cos i cap).|Un robot pequeño (cuerpo y cabeza).', 'El mateix robot al doble.|El mismo robot al doble.', 'Tots dos sobre la placa.|Los dos sobre la placa.'], nota: "Que els comparin des de davant: tenen la mateixa forma?|Que los comparen desde delante: ¿tienen la misma forma?" },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Una mida estira; Proporcional escala sense deformar.|Una medida estira; Proporcional escala sin deformar.', '2:1 és el doble i 1:2, la meitat.|2:1 es el doble y 1:2, la mitad.', 'En una figura, també s\'escalen les alçades.|En una figura, también se escalan las alturas.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['10 × 20 × 30 mm al doble?|¿10 × 20 × 30 mm al doble?', 'Per a què serveix Proporcional?|¿Para qué sirve Proporcional?'], nota: 'Respostes: 20 × 40 × 60 mm; perquè totes les mides canviïn alhora.|Respuestas: 20 × 40 × 60 mm; para que todas las medidas cambien a la vez.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: 'Busca una cosa i la seva versió en petit o en gran.|Busca una cosa y su versión en pequeño o en grande.', nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [
      { id: 'p1', t: 'Fitxa: dibuixa al doble|Ficha: dibuja al doble', k: 'fitxa', intro: "Dibuixa el robot de la pissarra a la quadrícula. Al doble, cada quadret es converteix en 2.|Dibuja el robot de la pizarra en la cuadrícula. Al doble, cada cuadrito se convierte en 2.",
        items: [{ q: "El cos fa 4 quadrets d'ample i 3 d'alt. Al doble: ____ d'ample i ____ d'alt.|El cuerpo mide 4 cuadritos de ancho y 3 de alto. Al doble: ____ de ancho y ____ de alto.", sol: "8 d'ample i 6 d'alt|8 de ancho y 6 de alto" }, { q: 'El cap fa 2 × 2 quadrets i comença al quadret 3 (des de baix). Al doble, on comença?|La cabeza mide 2 × 2 cuadritos y empieza en el cuadrito 3 (desde abajo). Al doble, ¿dónde empieza?', sol: 'Al quadret 6, i fa 4 × 4.|En el cuadrito 6, y mide 4 × 4.' },
          { q: 'Una caixa fa 12 × 8 × 6 mm. Com és a la meitat?|Una caja mide 12 × 8 × 6 mm. ¿Cómo es a la mitad?', sol: '6 × 4 × 3 mm|6 × 4 × 3 mm' }, { q: "Si fas un cub el doble d'ample, de fons i d'alt, quants cubs petits hi caben a dins?|Si haces un cubo el doble de ancho, de fondo y de alto, ¿cuántos cubos pequeños caben dentro?", sol: '8 (2 × 2 × 2)|8 (2 × 2 × 2)' }] }
    ]
  },
  /* ---------- Sessió 4 · Projecte: el robot de peces ---------- */
  'm3-4': {
    intro: "Sessió de projecte que tanca la unitat. L'alumnat construeix el robot de l'encàrrec a partir d'una fitxa tècnica: una taula amb les mides, la posició i el gir de cada peça. Primer la llegeixen i calculen les alçades sense pantalla; després el construeixen per parts i de baix a dalt, comprovant cada part abans de seguir. Al final el personalitzen i el desen al portafoli. És una bona sessió per observar l'autonomia i per avaluar la unitat amb la rúbrica.|Sesión de proyecto que cierra la unidad. El alumnado construye el robot del encargo a partir de una ficha técnica: una tabla con las medidas, la posición y el giro de cada pieza. Primero la leen y calculan las alturas sin pantalla; después lo construyen por partes y de abajo arriba, comprobando cada parte antes de seguir. Al final lo personalizan y lo guardan en el portafolio. Es una buena sesión para observar la autonomía y para evaluar la unidad con la rúbrica.",
    claus: ["Una fitxa tècnica permet que qualsevol persona construeixi exactament el mateix objecte.|Una ficha técnica permite que cualquier persona construya exactamente el mismo objeto.", "Es construeix per parts i de baix a dalt: cada peça comença on s'acaba la de sota.|Se construye por partes y de abajo arriba: cada pieza empieza donde acaba la de debajo.",
      "Les rodes i els braços són peces dretes tombades 90° en y.|Las ruedas y los brazos son piezas de pie tumbadas 90° en y.", "Comprovar cada part abans de passar a la següent estalvia haver de desfer-ho tot.|Comprobar cada parte antes de pasar a la siguiente ahorra tener que deshacerlo todo."],
    prev: ['Moure amb precisió, girar i escalar (les tres sessions anteriors).|Mover con precisión, girar y escalar (las tres sesiones anteriores).', "Llegir una taula amb files i columnes.|Leer una tabla con filas y columnas.", 'Sumar alçades de dues xifres.|Sumar alturas de dos cifras.'],
    obj: ["L'alumne/a interpreta una fitxa tècnica amb mides, posicions i girs.|El alumno/a interpreta una ficha técnica con medidas, posiciones y giros.",
      "L'alumne/a calcula l'alçada on comença cada peça sumant les de sota.|El alumno/a calcula la altura donde empieza cada pieza sumando las de debajo.",
      "L'alumne/a construeix un model de 10 peces combinant moure, girar i escalar.|El alumno/a construye un modelo de 10 piezas combinando mover, girar y escalar.",
      "L'alumne/a personalitza el seu robot mantenint-lo d'una sola peça i sobre la placa.|El alumno/a personaliza su robot manteniéndolo de una sola pieza y sobre la placa."],
    comp: ["Matemàtiques, sentit de la mesura: interpretar mides en mil·límetres en una taula|Matemáticas, sentido de la medida: interpretar medidas en milímetros en una tabla", "Matemàtiques, sentit espacial: posició, gir i composició de cossos|Matemáticas, sentido espacial: posición, giro y composición de cuerpos",
      "Tecnologia i digitalització: seguir una documentació tècnica i el procés de construcció d'un prototip|Tecnología y digitalización: seguir una documentación técnica y el proceso de construcción de un prototipo", "Competència personal: planificar i revisar la pròpia feina|Competencia personal: planificar y revisar el propio trabajo"],
    vocab: [['Fitxa tècnica|Ficha técnica', "Document amb les peces, les mides, la posició i el gir d'un objecte.|Documento con las piezas, las medidas, la posición y el giro de un objeto."], ['Especificació|Especificación', "Un requisit concret i mesurable: «el cos fa 26 × 18 × 24 mm».|Un requisito concreto y medible: «el cuerpo mide 26 × 18 × 24 mm»."], ['Pla de treball|Plan de trabajo', "L'ordre en què es construeixen les parts.|El orden en que se construyen las partes."],
      ['Muntatge|Montaje', 'Posar les peces juntes perquè formin l\'objecte.|Poner las piezas juntas para que formen el objeto.'], ['Personalitzar|Personalizar', 'Canviar un disseny perquè sigui teu, sense trencar el que és imprescindible.|Cambiar un diseño para que sea tuyo, sin romper lo imprescindible.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Projecte: el robot de peces»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Proyecto: el robot de piezas»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'La fitxa tècnica del robot impresa (una per alumne/a) i un llapis|La ficha técnica del robot impresa (una por alumno/a) y un lápiz'],
      imprimir: ['Fitxa tècnica del robot|Ficha técnica del robot', 'Targetes de la rúbrica del projecte|Tarjetas de la rúbrica del proyecto'], prep: ["Imprimir la fitxa tècnica i deixar-la a cada taula abans de començar.|Imprimir la ficha técnica y dejarla en cada mesa antes de empezar.", "Construir el robot a l'app abans de la classe per saber on s'encallen.|Construir el robot en la app antes de la clase para saber dónde se atascan.", "Pensar dos o tres idees de personalització per a qui no en tingui (barret, motxilla, braç saludant).|Pensar dos o tres ideas de personalización para quien no tenga (sombrero, mochila, brazo saludando)."] },
    plan: [
      { min: 5, t: 'El gran dia|El gran día', fase: 'inici', fa: "Presenta el projecte: la fitxa tècnica és a la taula i avui es construeix el robot. Ensenya el robot acabat girant-lo a la pissarra. Explica els criteris de la rúbrica.|Presenta el proyecto: la ficha técnica está en la mesa y hoy se construye el robot. Enseña el robot acabado girándolo en la pizarra. Explica los criterios de la rúbrica.",
        diu: ["Quantes peces té el robot? Quines estan girades?|¿Cuántas piezas tiene el robot? ¿Cuáles están giradas?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Llegir la fitxa i planificar|Leer la ficha y planificar', fase: 'teoria', fa: "Llegiu junts la fitxa tècnica: què vol dir cada columna. Expliqueu el pla de treball de baix a dalt i com se sumen les alçades. Recordeu que cal comprovar cada part abans de seguir.|Leed juntos la ficha técnica: qué quiere decir cada columna. Explicad el plan de trabajo de abajo arriba y cómo se suman las alturas. Recordad que hay que comprobar cada parte antes de seguir.",
        diu: ["El cos comença a z = 4 i fa 24 mm. On comença el cap?|El cuerpo empieza en z = 4 y mide 24 mm. ¿Dónde empieza la cabeza?", "Què vol dir «gir: 0°, 90°, 0°»?|¿Qué quiere decir «giro: 0°, 90°, 0°»?"], slides: ['s3', 's4', 's5', 's6'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'Llegeix la fitxa|Lee la ficha', fase: 'desconnectat', fa: "Cada alumne/a completa la columna de les alçades de la fitxa tècnica i encercla les peces girades. Després ho comparen per parelles i ho corregiu en veu alta.|Cada alumno/a completa la columna de las alturas de la ficha técnica y rodea las piezas giradas. Después lo comparan por parejas y lo corregís en voz alta.",
        diu: ["Mireu la peça de sota: on s'acaba?|Mirad la pieza de debajo: ¿dónde acaba?"], slides: ['s7'], app: 'Encara no: fitxa i llapis.|Todavía no: ficha y lápiz.', org: 'Individual i per parelles|Individual y por parejas' },
      { min: 22, t: 'Construir el robot per parts|Construir el robot por partes', fase: 'ordinador', fa: "Fan la sessió a l'app: arreglar les rodes, el cap, els ulls, els braços i l'antena, cada part amb les seves comprovacions. Deixa que treballin amb la fitxa al costat i que l'apuntin quan una part està feta. Intervén només quan una comprovació no es marca després de dos intents.|Hacen la sesión en la app: arreglar las ruedas, la cabeza, los ojos, los brazos y la antena, cada parte con sus comprobaciones. Deja que trabajen con la ficha al lado y que la marquen cuando una parte está hecha. Interviene solo cuando una comprobación no se marca después de dos intentos.",
        diu: ["Què diu la fitxa d'aquesta peça? Mida, posició i gir.|¿Qué dice la ficha de esta pieza? Medida, posición y giro.", 'Mira el robot des del costat: res flota?|Mira el robot desde el lado: ¿nada flota?'], slides: ['s8', 's9', 's10', 's11'], app: 'Sessió «Projecte: el robot de peces», fins a «El teu robot».|Sesión «Proyecto: el robot de piezas», hasta «Tu robot».', org: 'Individual|Individual' },
      { min: 10, t: 'El teu robot|Tu robot', fase: 'crea', fa: "Personalitzen el robot: colors, un braç girat 45° per saludar, un accessori. Ha de continuar sent una sola peça i amb totes les peces de la fitxa. Es desa al portafoli. Si hi ha temps, ho ensenyen a la parella i fan servir la rúbrica.|Personalizan el robot: colores, un brazo girado 45° para saludar, un accesorio. Tiene que seguir siendo una sola pieza y con todas las piezas de la ficha. Se guarda en el portafolio. Si hay tiempo, lo enseñan a la pareja y usan la rúbrica.",
        diu: ['Què has afegit? Està enganxat al robot?|¿Qué has añadido? ¿Está pegado al robot?'], slides: ['s12', 's13'], app: 'Pas «El teu robot».|Paso «Tu robot».', org: 'Individual i per parelles|Individual y por parejas' },
      { min: 5, t: 'Tancament i exposició|Cierre y exposición', fase: 'tancament', fa: "Projecta dos o tres robots del portafoli (amb permís) i comenteu què hi han afegit. Tiquet de sortida i resum de la unitat.|Proyecta dos o tres robots del portafolio (con permiso) y comentad qué han añadido. Ticket de salida y resumen de la unidad.",
        diu: ['Quina part us ha costat més? Com ho heu resolt?|¿Qué parte os ha costado más? ¿Cómo lo habéis resuelto?'], slides: ['s14', 's15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Posa el cap a z = 24 (l'alçada del cos) en lloc de z = 28.|Pone la cabeza en z = 24 (la altura del cuerpo) en lugar de z = 28.", "Recorda-li que el cos no comença a terra sinó a z = 4: s'acaba a 4 + 24 = 28.|Recuérdale que el cuerpo no empieza en el suelo sino en z = 4: acaba en 4 + 24 = 28."],
      ["Gira les rodes o els braços en z o en x i no queden com a la fitxa.|Gira las ruedas o los brazos en z o en x y no quedan como en la ficha.", "Que llegeixi el gir de la fitxa en ordre (x, y, z): el 90 és al mig, és a dir, en y.|Que lea el giro de la ficha en orden (x, y, z): el 90 está en el medio, es decir, en y."],
      ["Escala la bola dels ulls però la deixa a terra.|Escala la bola de los ojos pero la deja en el suelo.", "Escalar no la mou: després cal escriure la posició (x, y i z) a la pestanya Posició.|Escalar no la mueve: después hay que escribir la posición (x, y y z) en la pestaña Posición."],
      ["En personalitzar, afegeix una peça que no toca el robot i «una sola peça» deixa d'estar en verd.|Al personalizar, añade una pieza que no toca el robot y «una sola pieza» deja de estar en verde.", "Que miri la peça nova des de dos costats i la mogui fins que toqui una cara del robot.|Que mire la pieza nueva desde dos lados y la mueva hasta que toque una cara del robot."]],
    diff: { mes: "Fer el robot a escala 2:1 al costat del primer, o dissenyar una fitxa tècnica pròpia d'un altre robot perquè la construeixi un company.|Hacer el robot a escala 2:1 al lado del primero, o diseñar una ficha técnica propia de otro robot para que la construya un compañero.",
      menys: "Fer només els passos 1, 2 i 3 (cap, ulls i braços) i saltar l'antena. Tenir la fitxa amb les alçades ja calculades.|Hacer solo los pasos 1, 2 y 3 (cabeza, ojos y brazos) y saltar la antena. Tener la ficha con las alturas ya calculadas." },
    aval: { ticket: ['Quin és el millor ordre per construir un model gran?|¿Cuál es el mejor orden para construir un modelo grande?', 'Què vol dir «gir: 0°, 90°, 0°»?|¿Qué quiere decir «giro: 0°, 90°, 0°»?'],
      rubric: [['Seguir la fitxa|Seguir la ficha', 'Totes les peces tenen les mides, la posició i el gir de la fitxa.|Todas las piezas tienen las medidas, la posición y el giro de la ficha.', 'La majoria de peces són correctes, però alguna té una mida o un gir diferent.|La mayoría de piezas son correctas, pero alguna tiene una medida o un giro distinto.'],
        ['Construir de baix a dalt|Construir de abajo arriba', 'Calcula les alçades i res flota ni s\'enfonsa.|Calcula las alturas y nada flota ni se hunde.', "Necessita ajuda per calcular on comença alguna peça.|Necesita ayuda para calcular dónde empieza alguna pieza."],
        ['Personalització|Personalización', "Hi afegeix detalls propis i el robot continua sent d'una sola peça.|Le añade detalles propios y el robot sigue siendo de una sola pieza.", "Hi afegeix detalls, però queden peces soltes o en treu de la fitxa.|Le añade detalles, pero quedan piezas sueltas o quita piezas de la ficha."]] },
    casa: "Explica a algú de casa com has construït el robot: quantes peces té, quines has girat i per què el cap comença a z = 28. Si teniu ordinador, ensenyeu-li el portafoli.|Explica a alguien de casa cómo has construido el robot: cuántas piezas tiene, cuáles has girado y por qué la cabeza empieza en z = 28. Si tenéis ordenador, enseñadle el portafolio.",
    faq: [["Es pot imprimir el robot?|¿Se puede imprimir el robot?", "Sí: és una sola peça i toca la placa. Els ulls i la bola, però, són petits i rodons; per imprimir-los bé ho treballarem a la unitat 6.|Sí: es una sola pieza y toca la placa. Los ojos y la bola, sin embargo, son pequeños y redondos; para imprimirlos bien lo trabajaremos en la unidad 6."],
      ["Per què el cos comença a z = 4 i no a terra?|¿Por qué el cuerpo empieza en z = 4 y no en el suelo?", "Perquè el robot s'aguanta sobre les rodes i queda un espai de 4 mm entre el cos i el terra, com un cotxe.|Porque el robot se aguanta sobre las ruedas y queda un espacio de 4 mm entre el cuerpo y el suelo, como un coche."],
      ["I si un alumne/a vol fer un robot totalment diferent?|¿Y si un alumno/a quiere hacer un robot totalmente diferente?", "El projecte demana mantenir les peces de la fitxa, però pot canviar colors i afegir tot el que vulgui. Un robot nou pot ser el repte «més» o un projecte del laboratori.|El proyecto pide mantener las piezas de la ficha, pero puede cambiar colores y añadir todo lo que quiera. Un robot nuevo puede ser el reto «más» o un proyecto del laboratorio."]],
    tec: [["En desar el projecte, el botó està desactivat.|Al guardar el proyecto, el botón está desactivado.", "S'activa quan totes les comprovacions estan en verd: almenys 11 peces, 3 colors, una sola peça i a la placa.|Se activa cuando todas las comprobaciones están en verde: al menos 11 piezas, 3 colores, una sola pieza y en la placa."],
      ["Costa tocar els ulls perquè són molt petits.|Cuesta tocar los ojos porque son muy pequeños.", "Apropeu la vista amb dos dits o la roda del ratolí abans de tocar-los.|Acercad la vista con dos dedos o la rueda del ratón antes de tocarlos."],
      ["He mogut una peça sense voler i s'ha desmuntat una part.|He movido una pieza sin querer y se ha desmontado una parte.", "El botó de desfer (la fletxa de dalt) torna enrere pas a pas. A l'ordinador també funciona Ctrl + Z.|El botón de deshacer (la flecha de arriba) vuelve atrás paso a paso. En el ordenador también funciona Ctrl + Z."]],
    extra: ["Fer una exposició virtual: cada alumne/a tria la vista preferida del seu robot i en fa una captura per a un mural.|Hacer una exposición virtual: cada alumno/a elige la vista preferida de su robot y hace una captura para un mural.", "Escriure la fitxa tècnica del robot personalitzat, amb les peces noves.|Escribir la ficha técnica del robot personalizado, con las piezas nuevas.", "Construir el robot amb peces de construcció reals seguint la fitxa.|Construir el robot con piezas de construcción reales siguiendo la ficha."],
    trans: ['Unitat següent: construir amb alinear, duplicar i mirall (la casa del futur).|Unidad siguiente: construir con alinear, duplicar y espejo (la casa del futuro).', "Tecnologia: les fitxes tècniques i els plànols dels objectes que fem servir.|Tecnología: las fichas técnicas y los planos de los objetos que usamos."],
    slides: [
      { id: 's1', k: 'portada', t: 'Projecte: el robot de peces|Proyecto: el robot de piezas', x: 'Moure, girar i escalar per complir una fitxa tècnica|Mover, girar y escalar para cumplir una ficha técnica', nota: "Presenta el projecte final de la unitat: l'encàrrec de l'escola.|Presenta el proyecto final de la unidad: el encargo de la escuela." },
      { id: 's2', k: 'media', t: 'El robot acabat|El robot acabado', x: '10 peces: rodes, cos, braços, cap, ulls i antena.|10 piezas: ruedas, cuerpo, brazos, cabeza, ojos y antena.', media: { k: 'model', model: { parts: ROBOT } }, nota: "Gira'l davant de tothom i pregunta quines peces estan girades.|Gíralo delante de todos y pregunta qué piezas están giradas." },
      { id: 's3', k: 'anim', t: 'La fitxa tècnica|La ficha técnica', anim: 'm34fit', x: 'Mida, posició (z de la base) i gir de cada peça.|Medida, posición (z de la base) y giro de cada pieza.', nota: 'Llegiu una fila junts: «Cap · 20 × 16 × 14 · z = 28».|Leed una fila juntos: «Cabeza · 20 × 16 × 14 · z = 28».' },
      { id: 's4', k: 'anim', t: 'Pla de treball|Plan de trabajo', anim: 'm34pla', x: 'Per parts i de baix a dalt.|Por partes y de abajo arriba.', nota: "Expliqueu per què és millor aquest ordre: sempre saps on comença la peça següent.|Explicad por qué es mejor este orden: siempre sabes dónde empieza la pieza siguiente." },
      { id: 's5', k: 'pregunta', t: 'El cos comença a z = 4 i fa 24 mm. On comença el cap?|El cuerpo empieza en z = 4 y mide 24 mm. ¿Dónde empieza la cabeza?', x: "Pista: on s'acaba el cos?|Pista: ¿dónde acaba el cuerpo?", nota: 'Resposta: z = 28.|Respuesta: z = 28.' },
      { id: 's6', k: 'media', t: 'Les alçades, de davant|Las alturas, de frente', x: 'Rodes 0-16 · cos 4-28 · cap 28-42 · antena 42-50.|Ruedas 0-16 · cuerpo 4-28 · cabeza 28-42 · antena 42-50.', media: { k: 'model', model: { parts: ROBOT }, view: 'front' }, nota: 'Assenyala on s\'acaba cada peça i on comença la següent.|Señala dónde acaba cada pieza y dónde empieza la siguiente.' },
      { id: 's7', k: 'activitat', t: 'Llegeix la fitxa|Lee la ficha', timer: 7, punts: ['Encercla les peces girades.|Rodea las piezas giradas.', 'Calcula on comença cada peça (z).|Calcula dónde empieza cada pieza (z).', 'Compara-ho amb el company.|Compáralo con el compañero.'], nota: 'Corregiu-ho en veu alta abans de passar a l\'ordinador.|Corregidlo en voz alta antes de pasar al ordenador.' },
      { id: 's8', k: 'repte', t: "A l'ordinador: per parts|En el ordenador: por partes", punts: ['Arregla les rodes.|Arregla las ruedas.', 'Pas 1 i 2: el cap i els ulls.|Paso 1 y 2: la cabeza y los ojos.', 'Pas 3: els braços. Pas 4: l\'antena.|Paso 3: los brazos. Paso 4: la antena.'], nota: 'Una part, una comprovació. No passeu a la següent fins que tot estigui en verd.|Una parte, una comprobación. No paséis a la siguiente hasta que todo esté en verde.' },
      { id: 's9', k: 'media', t: 'Rodes i cos|Ruedas y cuerpo', x: 'Rodes: 90° en y, a x = −16 i x = 16.|Ruedas: 90° en y, en x = −16 y x = 16.', media: { k: 'model', model: { parts: ROBOT.slice(0, 3) } }, nota: 'Ajuda per a qui s\'encalli a la primera part.|Ayuda para quien se atasque en la primera parte.' },
      { id: 's10', k: 'concepte', t: 'Primer la mida, després la posició|Primero la medida, después la posición', x: "Quan una peça s'ha d'escalar i moure, canvia primer la mida i després escriu la posició: escalar no la mou.|Cuando una pieza se tiene que escalar y mover, cambia primero la medida y después escribe la posición: escalar no la mueve.", nota: 'Passa sobretot amb els ulls i l\'antena.|Pasa sobre todo con los ojos y la antena.' },
      { id: 's11', k: 'concepte', t: 'Comprova de dos costats|Comprueba desde dos lados', x: 'Mira el robot des de davant i des del costat: si una peça flota o s\'enfonsa, es veu de seguida.|Mira el robot desde delante y desde el lado: si una pieza flota o se hunde, se ve enseguida.', nota: "Recorda els botons de les vistes de dalt de la vista 3D.|Recuerda los botones de las vistas de arriba de la vista 3D." },
      { id: 's12', k: 'repte', t: 'El teu robot|Tu robot', punts: ['Canvia els colors.|Cambia los colores.', 'Gira un braç o afegeix un accessori.|Gira un brazo o añade un accesorio.', "Que continuï d'una sola peça.|Que siga siendo de una sola pieza."], nota: 'Recordeu els criteris de la rúbrica abans de desar.|Recordad los criterios de la rúbrica antes de guardar.' },
      { id: 's13', k: 'concepte', t: 'La rúbrica del projecte|La rúbrica del proyecto', x: "Segueix la fitxa · Res flota ni s'enfonsa · Té un detall teu i és d'una sola peça.|Sigue la ficha · Nada flota ni se hunde · Tiene un detalle tuyo y es de una sola pieza.", nota: "Per parelles, cada alumne/a valora el robot del company amb les targetes de la rúbrica.|Por parejas, cada alumno/a valora el robot del compañero con las tarjetas de la rúbrica." },
      { id: 's14', k: 'resum', t: 'Hem acabat la unitat!|¡Hemos acabado la unidad!', punts: ['Moure amb precisió, amb números.|Mover con precisión, con números.', 'Girar 15°, 45°, 90° i tombar peces.|Girar 15°, 45°, 90° y tumbar piezas.', 'Escalar al doble i a la meitat sense deformar.|Escalar al doble y a la mitad sin deformar.'], nota: 'Repassa les tres sessions anteriors amb exemples del robot.|Repasa las tres sesiones anteriores con ejemplos del robot.' },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Quin és el millor ordre per construir un model gran?|¿Cuál es el mejor orden para construir un modelo grande?', 'Què vol dir «gir: 0°, 90°, 0°»?|¿Qué quiere decir «giro: 0°, 90°, 0°»?'], nota: 'Respostes: de baix a dalt, per parts; girat 90° en y.|Respuestas: de abajo arriba, por partes; girado 90° en y.' },
      { id: 's16', k: 'concepte', t: 'A casa|En casa', x: "Explica a algú de casa com has fet el robot i per què el cap comença a z = 28.|Explica a alguien de casa cómo has hecho el robot y por qué la cabeza empieza en z = 28.", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [
      { id: 'p1', t: 'Fitxa tècnica del robot|Ficha técnica del robot', k: 'fitxa', intro: "Les mides són en mil·límetres (x × y × z). Completa on comença cada peça (z de la base). El gir va en ordre x, y, z.|Las medidas son en milímetros (x × y × z). Completa dónde empieza cada pieza (z de la base). El giro va en orden x, y, z.",
        items: [{ q: 'Rodes (2): cilindre 16 × 16 × 6 · x = −16 i 16 · gir 0°, 90°, 0° · z = ____|Ruedas (2): cilindro 16 × 16 × 6 · x = −16 y 16 · giro 0°, 90°, 0° · z = ____', sol: 'z = 0 (toquen la placa)|z = 0 (tocan la placa)' }, { q: 'Cos: caixa 26 × 18 × 24 · x = 0 · z = 4 · on s\'acaba? ____|Cuerpo: caja 26 × 18 × 24 · x = 0 · z = 4 · ¿dónde acaba? ____', sol: 'A z = 28 (4 + 24)|En z = 28 (4 + 24)' },
          { q: 'Cap: caixa 20 × 16 × 14 · x = 0 · z = ____ · on s\'acaba? ____|Cabeza: caja 20 × 16 × 14 · x = 0 · z = ____ · ¿dónde acaba? ____', sol: 'Comença a z = 28 i s\'acaba a z = 42.|Empieza en z = 28 y acaba en z = 42.' }, { q: 'Braços (2): caixa 6 × 6 × 20 · gir 0°, 90°, 0° · x = −23 i 23 · z = 20 · Encercla: estan girats?|Brazos (2): caja 6 × 6 × 20 · giro 0°, 90°, 0° · x = −23 y 23 · z = 20 · Rodea: ¿están girados?', sol: 'Sí: 90° en y (queden estirats).|Sí: 90° en y (quedan estirados).' },
          { q: 'Ulls (2): esfera 6 × 6 × 6 · x = −5 i 5 · y = −8 · z = 32. Antena: cilindre 2 × 2 × 8 · z = ____. Bola: esfera de 6 mm · z = ____|Ojos (2): esfera 6 × 6 × 6 · x = −5 y 5 · y = −8 · z = 32. Antena: cilindro 2 × 2 × 8 · z = ____. Bola: esfera de 6 mm · z = ____', sol: 'Antena a z = 42 i bola a z = 50.|Antena en z = 42 y bola en z = 50.' }] },
      { id: 'p2', t: 'Targetes de la rúbrica del projecte|Tarjetas de la rúbrica del proyecto', k: 'targetes', intro: "Per valorar el robot d'un company: marqueu cada targeta amb un ✓ (aconseguit) o un → (en procés).|Para valorar el robot de un compañero: marcad cada tarjeta con un ✓ (logrado) o un → (en proceso).",
        items: [{ t: 'Segueix la fitxa: mides, posició i gir|Sigue la ficha: medidas, posición y giro', n: 2 }, { t: "Res flota ni s'enfonsa|Nada flota ni se hunde", n: 2 }, { t: 'Té un detall propi i és una sola peça|Tiene un detalle propio y es una sola pieza', n: 2 }] }
    ]
  }
  };
})());

/* ── unitat 5 ── */
/* Tech 3D · Nivell 1 · unitat 5 «Forats» · guia del professor (m5-1 … m5-4)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1']. Les diapositives «media» mostren el
   model en 3D (TMEDIA.model): a la pissarra digital es pot girar amb el dit o amb el ratolí. */
Object.assign(TGUIDE, (() => {
  const P = (id, t, s, p, c, o = {}) => ({ id, t, s, p, r: o.r || [0, 0, 0], c, ...o });
  const H = (id, t, s, p, o = {}) => P(id, t, s, p, '#9AA3B5', { hole: true, ...o });
  const COIN = P('a1', 'cyl', [30, 30, 3], [0, 0, 1.5], '#F7C531');
  const COIN_DEMO = { parts: [COIN, H('f1', 'cyl', [8, 8, 10], [0, 0, 1.5])] };
  const BUT = P('a1', 'cyl', [30, 30, 4], [0, 0, 2], '#EC5FA8');
  const bh = (x, y, id) => H(id, 'cyl', [4, 4, 20], [x, y, 10]);
  const BUT4 = { parts: [BUT, bh(-5, 5, 'f1'), bh(5, 5, 'f2'), bh(-5, -5, 'f3'), bh(5, -5, 'f4')] };
  const DIE_BUIT = { parts: [P('a1', 'box', [20, 20, 20], [0, 0, 10], '#F3F3EE'), H('f1', 'box', [16, 16, 16], [0, 0, 10])] };
  const PL = P('a1', 'box', [40, 24, 4], [0, 0, 2], '#3D7BF4'), RING = (x, y) => H('f1', 'cyl', [5, 5, 20], [x, y, 10]);
  const KH = { parts: [P('a1', 'cyl', [36, 36, 4], [0, 0, 2], '#F7C531'), RING(0, 13), H('c1', 'heart', [14, 14, 3], [0, -2, 4.5])] };
  const KT = { parts: [PL, RING(-14, 0), H('t1', 'box', [14, 4, 3], [5, 5, 4.5]), H('t2', 'box', [4, 10, 3], [5, -2, 4.5])] };
  const CUP = P('a1', 'cyl', [40, 40, 50], [0, 0, 25], '#14A3B8');
  const TASSA = { parts: [CUP, H('f1', 'cyl', [36, 36, 50], [0, 0, 27])] };
  const TALL = { parts: [...TASSA.parts, H('tall', 'box', [50, 26, 60], [0, -13, 25])] };
  const NANSA = { parts: [...TASSA.parts, P('n1', 'torus', [24, 24, 5], [24, 0, 26], '#14A3B8', { r: [90, 0, 0] })] };
  const CAPSA = { parts: [P('a1', 'box', [60, 40, 30], [0, 0, 15], '#F5893A'), H('f1', 'box', [56, 36, 30], [0, 0, 17])] };
  const Fm = z => [P('f1', 'box', [4, 24, 2], [6, 0, z], '#F3F3EE'), P('f2', 'box', [16, 4, 2], [0, 10, z], '#F3F3EE'), P('f3', 'box', [12, 4, 2], [2, 0, z], '#F3F3EE')];
  const SEG = { parts: [P('m1', 'cyl', [24, 24, 26], [0, 0, 13], '#A0683A'), P('pl', 'box', [40, 40, 5], [0, 0, 28.5], '#3D7BF4'), ...Fm(32)] };
  const CARA = { parts: [P('pl', 'box', [40, 40, 5], [0, 0, 2.5], '#3D7BF4'), ...Fm(6)] };
  const LL = { parts: [P('l1', 'box', [4, 20, 3], [-22, 0, 1.5], '#E8453C'), P('l2', 'box', [12, 4, 3], [-18, -8, 1.5], '#E8453C'), P('l3', 'box', [4, 20, 3], [22, 0, 1.5], '#2FB36D'), P('l4', 'box', [12, 4, 3], [18, -8, 1.5], '#2FB36D')] };
  return {
  /* ---------- Sessió 1 · Formes buides ---------- */
  'm5-1': {
    obj: ["L'alumne/a explica que un forat és una forma que treu plàstic i el distingeix d'una peça sòlida.|El alumno/a explica que un agujero es una forma que quita plástico y lo distingue de una pieza sólida.",
      "L'alumne/a fa forats que travessen una peça fent-los més alts que la peça i els col·loca amb coordenades.|El alumno/a hace agujeros que atraviesan una pieza haciéndolos más altos que la pieza y los coloca con coordenadas.",
      "L'alumne/a duplica forats i en col·loca les còpies en posicions donades.|El alumno/a duplica agujeros y coloca las copias en posiciones dadas.",
      "L'alumne/a diferencia un forat passant, un clot i un buidat interior, i ho comprova amb el botó Resultat.|El alumno/a diferencia un agujero pasante, un hoyo y un vaciado interior, y lo comprueba con el botón Resultado."],
    comp: ["Matemàtiques, sentit espacial: cossos geomètrics i relacions entre ells (afegir i treure volums)|Matemáticas, sentido espacial: cuerpos geométricos y relaciones entre ellos (añadir y quitar volúmenes)",
      'Matemàtiques, sentit de la mesura: diàmetre, alçada i volum (mm i cm³)|Matemáticas, sentido de la medida: diámetro, altura y volumen (mm y cm³)',
      "Tecnologia i digitalització: operacions de disseny 3D (sòlid i forat) per fabricar objectes|Tecnología y digitalización: operaciones de diseño 3D (sólido y agujero) para fabricar objetos",
      "Pensament computacional: descompondre un objecte en peces que sumen i peces que resten|Pensamiento computacional: descomponer un objeto en piezas que suman y piezas que restan"],
    vocab: [['Forat|Agujero', "Peça que treu plàstic de les peces sòlides que toca. Es veu grisa i ratllada.|Pieza que quita plástico de las piezas sólidas que toca. Se ve gris y rayada."], ['Sòlid|Sólido', 'Peça que afegeix plàstic. Té color.|Pieza que añade plástico. Tiene color.'],
      ['Forat passant|Agujero pasante', 'Forat que travessa la peça de banda a banda.|Agujero que atraviesa la pieza de lado a lado.'], ['Clot|Hoyo', "Forat que només entra una mica a la peça.|Agujero que solo entra un poco en la pieza."],
      ['Buidat|Vaciado', 'Forat que queda tot a dins: la peça és buida però per fora no es nota.|Agujero que queda todo dentro: la pieza es hueca pero por fuera no se nota.'], ['Resultat|Resultado', "El botó que mostra l'objecte final amb els forats fets.|El botón que muestra el objeto final con los agujeros hechos."],
      ['Diàmetre|Diámetro', "L'amplada d'un cercle passant pel mig.|La anchura de un círculo pasando por el medio."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Formes buides»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Formas huecas»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "Plastilina, una palla i un tap d'ampolla per parella|Plastilina, una pajita y un tapón de botella por pareja"],
      imprimir: ['Fitxa: sòlid o forat?|Ficha: ¿sólido o agujero?'], prep: ["Preparar la plastilina en boles i tallar les palles perquè siguin més llargues que la moneda de plastilina.|Preparar la plastilina en bolas y cortar las pajitas para que sean más largas que la moneda de plastilina.", "Provar abans el botó Forat i el botó Resultat a l'ordinador de l'aula.|Probar antes el botón Agujero y el botón Resultado en el ordenador del aula.", 'Portar, si en teniu, botons de 2 i 4 forats i un dau per ensenyar-los.|Traer, si tenéis, botones de 2 y 4 agujeros y un dado para enseñarlos.'] },
    plan: [
      { min: 5, t: 'Els encàrrecs de la Remei|Los encargos de Remei', fase: 'inici', fa: "Presenta la unitat: fins ara només afegíem peces; avui aprendrem a treure plàstic. Ensenya un botó i un dau i pregunta com els farien amb el que saben.|Presenta la unidad: hasta ahora solo añadíamos piezas; hoy aprenderemos a quitar plástico. Enseña un botón y un dado y pregunta cómo los harían con lo que saben.",
        diu: ["Com faríeu els forats d'un botó si només podeu afegir peces?|¿Cómo haríais los agujeros de un botón si solo podéis añadir piezas?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Peces que treuen|Piezas que quitan', fase: 'teoria', fa: "Explica la diferència entre sòlid i forat amb l'animació. Gira la moneda a la pissarra en mode d'edició i després amb Resultat. Presenta les tres maneres (passant, clot, buidat) i com es mesura i es col·loca un forat.|Explica la diferencia entre sólido y agujero con la animación. Gira la moneda en la pizarra en modo de edición y después con Resultado. Presenta las tres maneras (pasante, hoyo, vaciado) y cómo se mide y se coloca un agujero.",
        diu: ["On és el forat quan mirem el Resultat?|¿Dónde está el agujero cuando miramos el Resultado?", "Per què el forat és més alt que la moneda?|¿Por qué el agujero es más alto que la moneda?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'Forats a la plastilina|Agujeros en la plastilina', fase: 'desconnectat', fa: "Per parelles fan dues monedes de plastilina: en una claven la palla de banda a banda (forat passant) i a l'altra premen el tap sense arribar a baix (clot). Comparen i ho apunten a la fitxa.|Por parejas hacen dos monedas de plastilina: en una clavan la pajita de lado a lado (agujero pasante) y en la otra aprietan el tapón sin llegar abajo (hoyo). Comparan y lo apuntan en la ficha.",
        diu: ['Hi veieu a través? Quin serviria per cosir un botó?|¿Veis a través? ¿Cuál serviría para coser un botón?'], slides: ['s8'], app: 'Encara no: plastilina i fitxa.|Todavía no: plastilina y ficha.', org: 'Per parelles|Por parejas' },
      { min: 22, t: 'Monedes, botons i daus|Monedas, botones y dados', fase: 'ordinador', fa: "Fan la sessió a l'app: troben el forat, prediuen el resultat, arreglen el botó, fan la moneda, el botó de quatre forats i el dau buit. Vigila que escriguin els números a Mida i Posició. El dau dels punts és un repte extra.|Hacen la sesión en la app: encuentran el agujero, predicen el resultado, arreglan el botón, hacen la moneda, el botón de cuatro agujeros y el dado hueco. Vigila que escriban los números en Medida y Posición. El dado de los puntos es un reto extra.",
        diu: ["Mira-ho de costat: el forat travessa o només fa un clot?|Míralo de lado: ¿el agujero atraviesa o solo hace un hoyo?", "Si toques un color, el forat torna a ser sòlid: compte!|Si tocas un color, el agujero vuelve a ser sólido: ¡cuidado!"], slides: ['s9', 's10', 's11'], app: "Sessió «Formes buides», fins al botó de la merceria.|Sesión «Formas huecas», hasta el botón de la mercería.", org: 'Individual|Individual' },
      { min: 8, t: 'El botó de la merceria|El botón de la mercería', fase: 'crea', fa: "Cada alumne/a dissenya el seu botó: forma i color lliures, almenys dos forats que el travessin i que no toquin la vora. Quan les comprovacions es marquen, el desen.|Cada alumno/a diseña su botón: forma y color libres, al menos dos agujeros que lo atraviesen y que no toquen el borde. Cuando las comprobaciones se marcan, lo guardan.",
        diu: ['Hi queda prou plàstic entre el forat i la vora?|¿Queda suficiente plástico entre el agujero y el borde?'], slides: ['s12'], app: 'Pas «El botó de la merceria».|Paso «El botón de la mercería».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa la idea clau (un forat treu plàstic) i les tres maneres. Tiquet de sortida i proposta per a casa.|Repasa la idea clave (un agujero quita plástico) y las tres maneras. Ticket de salida y propuesta para casa.",
        diu: ["Digueu-me un objecte amb un forat passant i un amb un clot.|Decidme un objeto con un agujero pasante y uno con un hoyo."], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["El forat no travessa: fa la mateixa alçada que la peça o està posat massa amunt.|El agujero no atraviesa: mide la misma altura que la pieza o está puesto demasiado arriba.", "Que ho miri des del costat i faci el forat més alt que la peça, amb la base a sota (z = 0 o menys).|Que lo mire desde el lado y haga el agujero más alto que la pieza, con la base debajo (z = 0 o menos)."],
      ["Converteix en forat la peça equivocada (la moneda) i tot desapareix.|Convierte en agujero la pieza equivocada (la moneda) y todo desaparece.", "Desfer (la fletxa) i tornar a seleccionar: el forat és la peça petita del mig.|Deshacer (la flecha) y volver a seleccionar: el agujero es la pieza pequeña del medio."],
      ['Toca un color per «pintar» el forat i torna a ser sòlid.|Toca un color para «pintar» el agujero y vuelve a ser sólido.', "Explica-li que els forats no tenen color: si en tries un, la peça torna a ser sòlida. Torna a tocar Forat.|Explícale que los agujeros no tienen color: si eliges uno, la pieza vuelve a ser sólida. Vuelve a tocar Agujero."],
      ['Arrossega el forat i queda una mica desplaçat del fantasma.|Arrastra el agujero y queda un poco desplazado del fantasma.', 'Que escrigui els números exactes a Posició: arrossegar és ràpid, però els números són exactes.|Que escriba los números exactos en Posición: arrastrar es rápido, pero los números son exactos.']],
    diff: { mes: "Fer el dau amb la cara del 5 o un botó en forma de flor amb sis forats en cercle. Explicar per què el dau buit gasta menys plàstic.|Hacer el dado con la cara del 5 o un botón en forma de flor con seis agujeros en círculo. Explicar por qué el dado hueco gasta menos plástico.",
      menys: "Fer la moneda junts a la pissarra pas a pas i deixar a la vista una targeta amb els números (Mida 8, Posició 0, 0). Al botó de quatre forats, fer-ne primer només dos.|Hacer la moneda juntos en la pizarra paso a paso y dejar a la vista una tarjeta con los números (Medida 8, Posición 0, 0). En el botón de cuatro agujeros, hacer primero solo dos." },
    aval: { ticket: ['Què fa una peça que és un forat?|¿Qué hace una pieza que es un agujero?', 'Com ha de ser un forat perquè travessi una moneda?|¿Cómo tiene que ser un agujero para que atraviese una moneda?'],
      rubric: [['Sòlid i forat|Sólido y agujero', "Explica que el forat treu plàstic i el converteix sense ajuda.|Explica que el agujero quita plástico y lo convierte sin ayuda.", 'Sap fer el forat, però li costa explicar què fa.|Sabe hacer el agujero, pero le cuesta explicar qué hace.'],
        ['Forat passant|Agujero pasante', 'Fa el forat més alt que la peça i ho comprova de costat.|Hace el agujero más alto que la pieza y lo comprueba de lado.', "De vegades fa clots sense voler i no ho comprova.|A veces hace hoyos sin querer y no lo comprueba."],
        ['Col·locar i duplicar|Colocar y duplicar', 'Col·loca forats amb números i duplica per fer-ne més.|Coloca agujeros con números y duplica para hacer más.', "Els col·loca a ull o els torna a fer d'un en un.|Los coloca a ojo o los vuelve a hacer de uno en uno."]] },
    casa: "Busqueu a casa objectes amb forats: passants (botons, rentadors, una ampolla sense tap), clots (motlles de gel, daus) o buits per dins (una pilota). Feu-ne una llista de tres columnes.|Buscad en casa objetos con agujeros: pasantes (botones, arandelas, una botella sin tapón), hoyos (moldes de hielo, dados) o huecos por dentro (una pelota). Haced una lista de tres columnas.",
    intro: "Primera sessió de la unitat dels forats, una de les idees més potents del modelatge 3D: amb ella l'alumnat podrà fer recipients, clauers i segells. Convé que surtin de la classe entenent que el forat és una peça més, que es mou i es mesura igual, però que treu plàstic.|Primera sesión de la unidad de los agujeros, una de las ideas más potentes del modelado 3D: con ella el alumnado podrá hacer recipientes, llaveros y sellos. Conviene que salgan de clase entendiendo que el agujero es una pieza más, que se mueve y se mide igual, pero que quita plástico.",
    claus: ['Un forat és una peça que treu plàstic de totes les peces sòlides que toca.|Un agujero es una pieza que quita plástico de todas las piezas sólidas que toca.', "Perquè travessi, el forat ha de ser més alt que la peça.|Para que atraviese, el agujero tiene que ser más alto que la pieza.",
      "El botó Resultat mostra l'objecte final, tal com el faria la impressora.|El botón Resultado muestra el objeto final, tal como lo haría la impresora.", 'Un forat que queda tot a dins buida la peça sense que es vegi: estalvia plàstic.|Un agujero que queda todo dentro vacía la pieza sin que se vea: ahorra plástico.'],
    prev: ['Saber col·locar una peça amb x, y i z (unitat 1) i duplicar peces (unitat 4).|Saber colocar una pieza con x, y y z (unidad 1) y duplicar piezas (unidad 4).', 'Saber canviar les mides d\'una peça a la pestanya Mida.|Saber cambiar las medidas de una pieza en la pestaña Medida.', 'No cal saber què és un volum: es presenta amb exemples.|No hace falta saber qué es un volumen: se presenta con ejemplos.'],
    faq: [['Un forat pot tenir qualsevol forma?|¿Un agujero puede tener cualquier forma?', "Sí: qualsevol forma de la paleta es pot convertir en forat amb el botó Forat (un cor, una estrella, una esfera…). A la paleta hi ha dreceres per al forat cúbic i el rodó.|Sí: cualquier forma de la paleta se puede convertir en agujero con el botón Agujero (un corazón, una estrella, una esfera…). En la paleta hay atajos para el agujero cúbico y el redondo."],
      ['Què passa si el forat toca dues peces?|¿Qué pasa si el agujero toca dos piezas?', "Les buida totes dues: al taller, els forats treuen plàstic de totes les peces sòlides. Si es vol que només en foradi una, s'agrupen el forat i aquella peça.|Las vacía las dos: en el taller, los agujeros quitan plástico de todas las piezas sólidas. Si se quiere que solo agujeree una, se agrupan el agujero y esa pieza."],
      ["Es pot imprimir un dau buit per dins?|¿Se puede imprimir un dado hueco por dentro?", "Sí: la impressora fa les parets i, a dalt, el sostre de 16 mm el fa com un pont, d'una paret a l'altra. A més, per estalviar, les impressores ja omplen les peces per dins amb un reticle, i no del tot.|Sí: la impresora hace las paredes y, arriba, el techo de 16 mm lo hace como un puente, de una pared a la otra. Además, para ahorrar, las impresoras ya rellenan las piezas por dentro con una retícula, y no del todo."]],
    tec: [['No trobo el botó Forat.|No encuentro el botón Agujero.', "Apareix a dalt de l'inspector quan hi ha una peça seleccionada, al costat de Duplica.|Aparece arriba del inspector cuando hay una pieza seleccionada, junto a Duplica."],
      ['El forat no es veu al Resultat.|El agujero no se ve en el Resultado.', "És normal: el forat ja no és una peça, només hi queda el buit. Si no hi ha buit, potser el forat no toca cap peça sòlida.|Es normal: el agujero ya no es una pieza, solo queda el hueco. Si no hay hueco, quizá el agujero no toca ninguna pieza sólida."],
      ['La vista va lenta quan hi ha molts forats.|La vista va lenta cuando hay muchos agujeros.', "Calcular els forats costa una mica a l'ordinador. Treballeu en mode d'edició i mireu el Resultat només per comprovar.|Calcular los agujeros cuesta un poco al ordenador. Trabajad en modo de edición y mirad el Resultado solo para comprobar."]],
    extra: ["Fer una col·lecció de botons de la classe i comparar quants forats tenen.|Hacer una colección de botones de la clase y comparar cuántos agujeros tienen.", "Dissenyar un dau sencer amb els sis números (cada cara oposada suma 7).|Diseñar un dado entero con los seis números (cada cara opuesta suma 7).", "Endevinar l'objecte: un company descriu un objecte només amb les peces sòlides i els forats que té.|Adivinar el objeto: un compañero describe un objeto solo con las piezas sólidas y los agujeros que tiene."],
    trans: ['Sessió següent: un clauer amb forat per a l\'anella i un dibuix gravat.|Sesión siguiente: un llavero con agujero para la anilla y un dibujo grabado.', 'Matemàtiques: el cercle, el diàmetre i el volum.|Matemáticas: el círculo, el diámetro y el volumen.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Formes buides|Formas huecas', x: 'Peces que treuen plàstic: els forats|Piezas que quitan plástico: los agujeros', nota: "Presenta els encàrrecs: botons per a la merceria i daus per a la classe de mates.|Presenta los encargos: botones para la mercería y dados para la clase de mates." },
      { id: 's2', k: 'pregunta', t: "Com faríeu els forats d'un botó?|¿Cómo haríais los agujeros de un botón?", x: 'Fins ara només sabíem afegir peces…|Hasta ahora solo sabíamos añadir piezas…', nota: "Recull idees. Algú pot proposar fer el botó amb trossos; arribeu a la idea que cal una manera de treure plàstic.|Recoge ideas. Alguien puede proponer hacer el botón con trozos; llegad a la idea de que hace falta una manera de quitar plástico." },
      { id: 's3', k: 'anim', t: 'Sòlid i forat|Sólido y agujero', anim: 'm5forat', x: 'El forat és com una goma d\'esborrar amb forma.|El agujero es como una goma de borrar con forma.', nota: "Insisteix que el forat es veu gris i ratllat i que no té color.|Insiste en que el agujero se ve gris y rayado y que no tiene color." },
      { id: 's4', k: 'media', t: 'Un forat passant|Un agujero pasante', x: 'El forat (10 mm) és més alt que la moneda (3 mm).|El agujero (10 mm) es más alto que la moneda (3 mm).', media: { k: 'model', model: COIN_DEMO, mode: 'edit' }, nota: 'Gira-la per veure que el forat sobresurt per dalt i per baix.|Gírala para ver que el agujero sobresale por arriba y por abajo.' },
      { id: 's5', k: 'media', t: 'El Resultat|El Resultado', x: 'Així la faria la Nuvi.|Así la haría Nuvi.', media: { k: 'model', model: COIN_DEMO }, nota: "Compara-la amb la diapositiva anterior: on és ara el forat?|Compárala con la diapositiva anterior: ¿dónde está ahora el agujero?" },
      { id: 's6', k: 'anim', t: 'Tres maneres|Tres maneras', anim: 'm5tipus', x: 'Passant, clot o buit per dins.|Pasante, hoyo o hueco por dentro.', nota: "Demana exemples de cada tipus: un botó, un dau, un ou de xocolata.|Pide ejemplos de cada tipo: un botón, un dado, un huevo de chocolate." },
      { id: 's7', k: 'media', t: 'Mida i lloc del forat|Medida y lugar del agujero', x: 'Quatre forats de 4 mm a x = ±5, y = ±5.|Cuatro agujeros de 4 mm en x = ±5, y = ±5.', media: { k: 'model', model: BUT4, view: 'top' }, nota: 'Llegiu junts les coordenades dels quatre forats.|Leed juntos las coordenadas de los cuatro agujeros.' },
      { id: 's8', k: 'activitat', t: 'Forats a la plastilina|Agujeros en la plastilina', timer: 7, punts: ['Fes dues monedes de plastilina.|Haz dos monedas de plastilina.', 'A una, clava-hi la palla de banda a banda.|En una, clava la pajita de lado a lado.', "A l'altra, prem el tap sense arribar a baix.|En la otra, aprieta el tapón sin llegar abajo."], nota: 'Per parelles. Ho apunten a la fitxa.|Por parejas. Lo apuntan en la ficha.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['La moneda amb forat.|La moneda con agujero.', 'El botó de quatre forats.|El botón de cuatro agujeros.', 'El dau buit per dins.|El dado hueco por dentro.'], nota: "Recorda: el forat rodó és a la paleta i els números van a Mida i Posició.|Recuerda: el agujero redondo está en la paleta y los números van en Medida y Posición." },
      { id: 's10', k: 'media', t: 'El dau buit|El dado hueco', x: 'Per fora no es nota, però gasta la meitat de plàstic.|Por fuera no se nota, pero gasta la mitad de plástico.', media: { k: 'model', model: DIE_BUIT, mode: 'edit' }, nota: "Ajuda per a qui s'encalli: el forat de 16 mm comença a z = 2.|Ayuda para quien se atasque: el agujero de 16 mm empieza en z = 2." },
      { id: 's11', k: 'concepte', t: 'Duplicar forats|Duplicar agujeros', x: "Selecciona el forat, toca Duplica i canvia la x i la y de la còpia. La còpia també és un forat.|Selecciona el agujero, toca Duplica y cambia la x y la y de la copia. La copia también es un agujero.", nota: 'Útil per al botó de quatre forats i per als punts del dau.|Útil para el botón de cuatro agujeros y para los puntos del dado.' },
      { id: 's12', k: 'repte', t: 'El botó de la merceria|El botón de la mercería', punts: ['Forma i color lliures.|Forma y color libres.', 'Almenys 2 forats que el travessin.|Al menos 2 agujeros que lo atraviesen.', 'Que els forats no toquin la vora.|Que los agujeros no toquen el borde.'], nota: "Activitat oberta: les comprovacions avisen si falta algun forat.|Actividad abierta: las comprobaciones avisan si falta algún agujero." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Un forat treu plàstic.|Un agujero quita plástico.', "Perquè travessi, ha de ser més alt que la peça.|Para que atraviese, tiene que ser más alto que la pieza.", 'El botó Resultat mostra l\'objecte final.|El botón Resultado muestra el objeto final.'], nota: 'Llegiu-ho junts en veu alta.|Leedlo juntos en voz alta.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Què fa una peça que és un forat?|¿Qué hace una pieza que es un agujero?', 'Com ha de ser un forat perquè travessi una moneda?|¿Cómo tiene que ser un agujero para que atraviese una moneda?'], nota: 'Oral o escrit al darrere de la fitxa.|Oral o escrito detrás de la ficha.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: 'Busca objectes amb forats passants, clots i buits per dins.|Busca objetos con agujeros pasantes, hoyos y huecos por dentro.', nota: 'La sessió següent podeu començar posant en comú les llistes.|En la sesión siguiente podéis empezar poniendo en común las listas.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: sòlid o forat?|Ficha: ¿sólido o agujero?', k: 'fitxa', intro: "Respon després de l'activitat de plastilina.|Responde después de la actividad de plastilina.",
      items: [{ q: 'Amb la palla, has fet un forat passant o un clot? Com ho saps?|Con la pajita, ¿has hecho un agujero pasante o un hoyo? ¿Cómo lo sabes?', sol: 'Un forat passant: hi veig a través.|Un agujero pasante: veo a través.' },
        { q: 'Amb el tap, has fet un forat passant o un clot?|Con el tapón, ¿has hecho un agujero pasante o un hoyo?', sol: 'Un clot: no arriba a baix.|Un hoyo: no llega abajo.' },
        { q: 'Una moneda fa 3 mm de gruix. Quina alçada ha de tenir el forat perquè la travessi?|Una moneda mide 3 mm de grosor. ¿Qué altura tiene que tener el agujero para que la atraviese?', sol: 'Més de 3 mm (per exemple, 10 mm), que sobresurti per dalt i per baix.|Más de 3 mm (por ejemplo, 10 mm), que sobresalga por arriba y por abajo.' },
        { q: 'Escriu un objecte que sigui buit per dins però que per fora no ho sembli.|Escribe un objeto que sea hueco por dentro pero que por fuera no lo parezca.', sol: "Per exemple: un ou de xocolata, una pilota, una guardiola.|Por ejemplo: un huevo de chocolate, una pelota, una hucha." }] }]
  },
  /* ---------- Sessió 2 · Un clauer ---------- */
  'm5-2': {
    obj: ["L'alumne/a dissenya un clauer de 3-4 mm de gruix amb un forat per a l'anella que deixa prou vora.|El alumno/a diseña un llavero de 3-4 mm de grosor con un agujero para la anilla que deja suficiente borde.",
      "L'alumne/a grava una forma a 1 mm de fondària calculant la z de la base del forat.|El alumno/a graba una forma a 1 mm de profundidad calculando la z de la base del agujero.",
      "L'alumne/a construeix una lletra amb caixes i la converteix en gravat o en relleu.|El alumno/a construye una letra con cajas y la convierte en grabado o en relieve.",
      "L'alumne/a detecta errors de disseny (forat a la vora, peça massa prima) i els corregeix.|El alumno/a detecta errores de diseño (agujero en el borde, pieza demasiado fina) y los corrige."],
    comp: ['Matemàtiques, sentit de la mesura: mesures en mm, restes de longituds (4 − 1 = 3)|Matemáticas, sentido de la medida: medidas en mm, restas de longitudes (4 − 1 = 3)', "Matemàtiques, sentit espacial: descompondre lletres en rectangles|Matemáticas, sentido espacial: descomponer letras en rectángulos",
      'Tecnologia i digitalització: disseny d\'un objecte útil pensant en la resistència|Tecnología y digitalización: diseño de un objeto útil pensando en la resistencia', 'Educació en valors: un objecte per a una fira solidària|Educación en valores: un objeto para una feria solidaria'],
    vocab: [['Gravar|Grabar', 'Fer un dibuix enfonsat amb un forat poc profund.|Hacer un dibujo hundido con un agujero poco profundo.'], ['Relleu|Relieve', 'Dibuix que sobresurt, fet amb peces sòlides a sobre.|Dibujo que sobresale, hecho con piezas sólidas encima.'], ['Fondària|Profundidad', 'Quant entra un gravat a la peça.|Cuánto entra un grabado en la pieza.'],
      ['Gruix|Grosor', 'La mida de la peça de baix a dalt.|La medida de la pieza de abajo arriba.'], ['Vora|Borde', "El plàstic que queda entre el forat i el contorn de la peça.|El plástico que queda entre el agujero y el contorno de la pieza."], ['Traç|Trazo', 'Cadascuna de les ratlles que formen una lletra.|Cada una de las rayas que forman una letra.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Un clauer»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Un llavero»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Paper quadriculat, regles, tisores i una anella de clauer o un clip per alumne/a|Papel cuadriculado, reglas, tijeras y una anilla de llavero o un clip por alumno/a'],
      imprimir: ['Fitxa: el meu clauer en paper|Ficha: mi llavero en papel'], prep: ["Si teniu un clauer imprès o comprat, portar-lo per ensenyar el gruix i la vora de l'anella.|Si tenéis un llavero impreso o comprado, traerlo para enseñar el grosor y el borde de la anilla.", "Provar el repte del cor gravat: cal posar z = 3.|Probar el reto del corazón grabado: hay que poner z = 3.", 'Imprimir la fitxa en paper quadriculat de 5 mm o fer-la servir de guia.|Imprimir la ficha en papel cuadriculado de 5 mm o usarla de guía.'] },
    plan: [
      { min: 5, t: 'La fira solidària|La feria solidaria', fase: 'inici', fa: "Presenta l'encàrrec: clauers per a la fira solidària de l'escola. Ensenya un clauer real i pregunteu-vos què el fa resistent.|Presenta el encargo: llaveros para la feria solidaria de la escuela. Enseña un llavero real y preguntaos qué lo hace resistente.",
        diu: ['On es trencaria primer aquest clauer?|¿Por dónde se rompería primero este llavero?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Gruix, anella i gravat|Grosor, anilla y grabado', fase: 'teoria', fa: "Explica les parts d'un bon clauer amb l'animació. Mostra el cor gravat en 3D i calcula junts la z del gravat (4 − 1 = 3). Compara gravat i relleu i ensenya com es fa una lletra amb caixes.|Explica las partes de un buen llavero con la animación. Muestra el corazón grabado en 3D y calculad juntos la z del grabado (4 − 1 = 3). Compara grabado y relieve y enseña cómo se hace una letra con cajas.",
        diu: ["Si el clauer fa 4 mm i vull gravar 1 mm, on comença el forat?|Si el llavero mide 4 mm y quiero grabar 1 mm, ¿dónde empieza el agujero?", 'Quantes caixes necessito per fer una E?|¿Cuántas cajas necesito para hacer una E?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'El clauer en paper|El llavero en papel', fase: 'desconnectat', fa: "Dibuixen el clauer a mida real en paper quadriculat, marquen el forat de l'anella amb un quadret de vora i dissenyen la inicial amb rectangles. El retallen i el proven amb l'anella.|Dibujan el llavero a tamaño real en papel cuadriculado, marcan el agujero de la anilla con un cuadrito de borde y diseñan la inicial con rectángulos. Lo recortan y lo prueban con la anilla.",
        diu: ["Cada quadret fa 5 mm: quants mil·límetres de vora has deixat?|Cada cuadrito mide 5 mm: ¿cuántos milímetros de borde has dejado?"], slides: ['s8'], app: 'Encara no: paper, regle i tisores.|Todavía no: papel, regla y tijeras.', org: 'Individual|Individual' },
      { min: 20, t: "A l'ordinador: anella, cor i T|En el ordenador: anilla, corazón y T", fase: 'ordinador', fa: "Fan la sessió a l'app: comparen clauers, arreglen el forat de la vora, fan el forat de l'anella, graven el cor i la T. El clauer massa prim és un repte extra. Comprova que posen la z correcta als gravats.|Hacen la sesión en la app: comparan llaveros, arreglan el agujero del borde, hacen el agujero de la anilla, graban el corazón y la T. El llavero demasiado fino es un reto extra. Comprueba que ponen la z correcta en los grabados.",
        diu: ["Mira el gravat de costat: entra 1 mm o travessa?|Mira el grabado de lado: ¿entra 1 mm o atraviesa?"], slides: ['s9', 's10', 's11'], app: 'Sessió «Un clauer», fins a «El meu clauer per a la fira».|Sesión «Un llavero», hasta «Mi llavero para la feria».', org: 'Individual|Individual' },
      { min: 8, t: 'El meu clauer|Mi llavero', fase: 'crea', fa: "Cada alumne/a fa el seu clauer amb la inicial que ha dissenyat en paper. Les comprovacions vigilen el forat, el gruix i que res no sigui massa prim.|Cada alumno/a hace su llavero con la inicial que ha diseñado en papel. Las comprobaciones vigilan el agujero, el grosor y que nada sea demasiado fino.",
        diu: ["La teva lletra és igual que la del paper?|¿Tu letra es igual que la del papel?"], slides: ['s12'], app: 'Pas «El meu clauer per a la fira».|Paso «Mi llavero para la feria».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa les tres regles del clauer i el càlcul de la z del gravat. Tiquet de sortida.|Repasa las tres reglas del llavero y el cálculo de la z del grabado. Ticket de salida.",
        diu: ['Quines són les tres regles d\'un bon clauer?|¿Cuáles son las tres reglas de un buen llavero?'], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Posa el gravat a z = 0 i travessa tot el clauer.|Pone el grabado en z = 0 y atraviesa todo el llavero.", "Que ho miri des del costat. Calculeu junts: gruix − fondària = 4 − 1 = 3.|Que lo mire desde el lado. Calculad juntos: grosor − profundidad = 4 − 1 = 3."],
      ["Fa el forat de l'anella tan a la vora que la trenca.|Hace el agujero de la anilla tan en el borde que lo rompe.", "Que miri el Resultat des de dalt: hi ha d'haver plàstic tot al voltant del forat, uns 2-3 mm.|Que mire el Resultado desde arriba: tiene que haber plástico todo alrededor del agujero, unos 2-3 mm."],
      ["Fa els traços de la lletra de 1 mm i no es veuen.|Hace los trazos de la letra de 1 mm y no se ven.", "Recorda la regla: traços d'almenys 3 mm. Al paper, mig quadret.|Recuerda la regla: trazos de al menos 3 mm. En el papel, medio cuadrito."],
      ["La lletra surt al revés quan la mira des de dalt.|La letra sale al revés cuando la mira desde arriba.", "Que posi la vista de dalt (planta) abans de construir-la. Per al clauer la lletra va del dret; al segell, en canvi, anirà al revés.|Que ponga la vista de arriba (planta) antes de construirla. Para el llavero la letra va del derecho; en el sello, en cambio, irá al revés."]],
    diff: { mes: "Gravar les dues inicials o una paraula curta, o combinar un gravat i un relleu al mateix clauer.|Grabar las dos iniciales o una palabra corta, o combinar un grabado y un relieve en el mismo llavero.",
      menys: "Fer un clauer amb una forma de la paleta (cor, estrella) gravada, sense lletres. Deixar la regla «gruix − 1» escrita a la pissarra.|Hacer un llavero con una forma de la paleta (corazón, estrella) grabada, sin letras. Dejar la regla «grosor − 1» escrita en la pizarra." },
    aval: { ticket: ["Un clauer fa 4 mm. On comença un gravat d'1 mm?|Un llavero mide 4 mm. ¿Dónde empieza un grabado de 1 mm?", "Per què el forat de l'anella no pot tocar la vora?|¿Por qué el agujero de la anilla no puede tocar el borde?"],
      rubric: [["Forat de l'anella|Agujero de la anilla", 'El col·loca amb 2-3 mm de vora i ho comprova.|Lo coloca con 2-3 mm de borde y lo comprueba.', 'El col·loca, però massa a prop de la vora.|Lo coloca, pero demasiado cerca del borde.'],
        ['Gravat|Grabado', 'Calcula la z del gravat i el fa d\'1 mm.|Calcula la z del grabado y lo hace de 1 mm.', 'El gravat travessa o queda fora de la peça.|El grabado atraviesa o queda fuera de la pieza.'],
        ['Lletra amb formes|Letra con formas', 'Construeix la inicial amb traços de 3 mm o més.|Construye la inicial con trazos de 3 mm o más.', 'La lletra té traços massa prims o peces separades.|La letra tiene trazos demasiado finos o piezas separadas.']] },
    casa: "Mireu els clauers de casa: de quin material són, quant fan de gruix i quanta vora té el forat de l'anella? Dibuixeu-ne un a mida real.|Mirad los llaveros de casa: ¿de qué material son, cuánto miden de grosor y cuánto borde tiene el agujero de la anilla? Dibujad uno a tamaño real.",
    intro: "Primer objecte útil de la unitat: un clauer. És una bona ocasió per parlar de disseny pensant en l'ús (es penja, es frega, es doblega) i per fer càlculs senzills amb mil·límetres.|Primer objeto útil de la unidad: un llavero. Es una buena ocasión para hablar de diseño pensando en el uso (se cuelga, se frota, se dobla) y para hacer cálculos sencillos con milímetros.",
    claus: ["Un clauer fort fa 3-4 mm de gruix.|Un llavero fuerte mide 3-4 mm de grosor.", "El forat de l'anella necessita 2-3 mm de vora.|El agujero de la anilla necesita 2-3 mm de borde.", 'Un gravat és un forat poc profund: la seva base va a gruix − fondària.|Un grabado es un agujero poco profundo: su base va a grosor − profundidad.', "Les lletres es construeixen amb caixes, amb traços d'almenys 3 mm.|Las letras se construyen con cajas, con trazos de al menos 3 mm."],
    prev: ['Haver fet «Formes buides»: convertir una peça en forat.|Haber hecho «Formas huecas»: convertir una pieza en agujero.', "Saber posar la z d'una peça a Posició.|Saber poner la z de una pieza en Posición.", 'Saber restar nombres petits.|Saber restar números pequeños.'],
    faq: [["Podem imprimir els clauers per a la fira?|¿Podemos imprimir los llaveros para la feria?", "Sí, si teniu impressora: és una peça petita i ràpida. Exporteu-los des de «Projectes» amb el botó STL (ho veurem a la unitat 6).|Sí, si tenéis impresora: es una pieza pequeña y rápida. Exportadlos desde «Proyectos» con el botón STL (lo veremos en la unidad 6)."],
      ["Per què un gravat d'1 mm i no més?|¿Por qué un grabado de 1 mm y no más?", "Perquè es noti i es vegi bé però a sota quedi prou plàstic. En un clauer de 4 mm, gravar-ne 2 encara aniria bé; gravar-ne 4 el travessaria.|Para que se note y se vea bien pero debajo quede suficiente plástico. En un llavero de 4 mm, grabar 2 todavía iría bien; grabar 4 lo atravesaría."],
      ['El gravat es pot pintar?|¿El grabado se puede pintar?', "Sí: un truc habitual és pintar el clot amb pintura acrílica i netejar la superfície. Una altra opció és el relleu d'un altre color.|Sí: un truco habitual es pintar el hoyo con pintura acrílica y limpiar la superficie. Otra opción es el relieve de otro color."]],
    tec: [["No puc convertir el cor en forat.|No puedo convertir el corazón en agujero.", "Selecciona el cor (que surti a l'inspector) i toca el botó Forat de dalt.|Selecciona el corazón (que salga en el inspector) y toca el botón Agujero de arriba."],
      ['El gravat no es veu a la vista normal.|El grabado no se ve en la vista normal.', "En mode d'edició el forat es veu ratllat a sobre; toqueu Resultat per veure el clot.|En modo de edición el agujero se ve rayado encima; tocad Resultado para ver el hoyo."],
      ["La comprovació del gravat no es marca.|La comprobación del grabado no se marca.", "Comproveu la mida (14 × 14), la posició (0, −2) i la z = 3. Si el cor travessa, la z és massa baixa.|Comprobad la medida (14 × 14), la posición (0, −2) y la z = 3. Si el corazón atraviesa, la z es demasiado baja."]],
    extra: ['Fer una paradeta de prova: cada alumne/a explica el seu clauer com si el vengués.|Hacer un puesto de prueba: cada alumno/a explica su llavero como si lo vendiera.', 'Dissenyar l\'alfabet de caixes: quantes caixes necessita cada lletra?|Diseñar el alfabeto de cajas: ¿cuántas cajas necesita cada letra?', 'Fer clauers en relleu de dos colors.|Hacer llaveros en relieve de dos colores.'],
    trans: ['Sessió següent: caixes i tasses (recipients amb parets i fons).|Sesión siguiente: cajas y tazas (recipientes con paredes y fondo).', 'Llengua: les lletres i la seva forma (traços rectes i corbs).|Lengua: las letras y su forma (trazos rectos y curvos).'],
    slides: [
      { id: 's1', k: 'portada', t: 'Un clauer|Un llavero', x: 'Clauers amb inicials per a la fira solidària|Llaveros con iniciales para la feria solidaria', nota: "Presenta l'encàrrec i la causa: llibres per a la biblioteca.|Presenta el encargo y la causa: libros para la biblioteca." },
      { id: 's2', k: 'pregunta', t: 'Què fa que un clauer sigui fort?|¿Qué hace que un llavero sea fuerte?', x: 'Pensa en la motxilla: es penja, es frega, cau…|Piensa en la mochila: se cuelga, se frota, se cae…', nota: 'Busquem tres idees: gruix, vora del forat i material.|Buscamos tres ideas: grosor, borde del agujero y material.' },
      { id: 's3', k: 'anim', t: "Les parts d'un clauer|Las partes de un llavero", anim: 'm5clauer', x: "Gruix de 4 mm, vora de 3 mm i gravat d'1 mm.|Grosor de 4 mm, borde de 3 mm y grabado de 1 mm.", nota: "Fes que assenyalin cada part en un clauer real.|Haz que señalen cada parte en un llavero real." },
      { id: 's4', k: 'media', t: 'Un cor gravat|Un corazón grabado', x: 'El cor és un forat que només entra 1 mm.|El corazón es un agujero que solo entra 1 mm.', media: { k: 'model', model: KH }, nota: 'Gira el clauer per veure el clot del cor i el forat de l\'anella.|Gira el llavero para ver el hoyo del corazón y el agujero de la anilla.' },
      { id: 's5', k: 'pregunta', t: "Un clauer de 4 mm i un gravat d'1 mm: a quina z comença el forat?|Un llavero de 4 mm y un grabado de 1 mm: ¿en qué z empieza el agujero?", x: 'Pista: gruix − fondària.|Pista: grosor − profundidad.', nota: 'Resposta: z = 3. Ho necessitaran als reptes.|Respuesta: z = 3. Lo necesitarán en los retos.' },
      { id: 's6', k: 'anim', t: 'Gravat o relleu|Grabado o relieve', anim: 'm5relleu', x: 'Enfonsat o sobresortint.|Hundido o sobresaliendo.', nota: 'Tots dos funcionen: que triïn el que vulguin al projecte.|Los dos funcionan: que elijan el que quieran en el proyecto.' },
      { id: 's7', k: 'media', t: 'Una T amb dues caixes|Una T con dos cajas', x: 'Barra de 14 × 4 mm i pal de 4 × 10 mm.|Barra de 14 × 4 mm y palo de 4 × 10 mm.', media: { k: 'model', model: KT, view: 'top' }, nota: "Pregunta quantes caixes caldrien per a la L, la E o la H.|Pregunta cuántas cajas harían falta para la L, la E o la H." },
      { id: 's8', k: 'activitat', t: 'El clauer en paper|El llavero en papel', timer: 9, punts: ['Dibuixa el contorn a mida real.|Dibuja el contorno a tamaño real.', "Marca el forat de l'anella amb vora.|Marca el agujero de la anilla con borde.", 'Dissenya la inicial amb rectangles.|Diseña la inicial con rectángulos.'], nota: "Cada quadret fa 5 mm. Que el retallin i el provin amb l'anella.|Cada cuadrito mide 5 mm. Que lo recorten y lo prueben con la anilla." },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ["El forat de l'anella.|El agujero de la anilla.", 'El cor gravat.|El corazón grabado.', 'La T gravada.|La T grabada.'], nota: 'Recorda: als gravats, z = 3.|Recuerda: en los grabados, z = 3.' },
      { id: 's10', k: 'concepte', t: 'La vora del forat|El borde del agujero', x: "Entre el forat i el contorn hi ha d'haver 2-3 mm de plàstic. Si no, l'anella el trenca.|Entre el agujero y el contorno tiene que haber 2-3 mm de plástico. Si no, la anilla lo rompe.", nota: "Connecta amb el clauer rosa del primer repte, que tenia la vora trencada.|Conecta con el llavero rosa del primer reto, que tenía el borde roto." },
      { id: 's11', k: 'concepte', t: 'Traços de 3 mm|Trazos de 3 mm', x: "Si els traços de la lletra són massa prims, la impressora no els marca bé.|Si los trazos de la letra son demasiado finos, la impresora no los marca bien.", nota: 'Ho retrobaran a la unitat 6, amb el gruix de les parets.|Lo volverán a encontrar en la unidad 6, con el grosor de las paredes.' },
      { id: 's12', k: 'repte', t: 'El meu clauer per a la fira|Mi llavero para la feria', punts: ['Forma lliure i forat amb vora.|Forma libre y agujero con borde.', 'Gruix de 3-4 mm.|Grosor de 3-4 mm.', 'Inicial o dibuix gravat o en relleu.|Inicial o dibujo grabado o en relieve.'], nota: 'Que facin servir el disseny en paper com a plànol.|Que usen el diseño en papel como plano.' },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Un clauer fort: 3-4 mm de gruix i vora a l'anella.|Un llavero fuerte: 3-4 mm de grosor y borde en la anilla.", 'Gravar: forat poc profund (z = gruix − fondària).|Grabar: agujero poco profundo (z = grosor − profundidad).', 'Lletres amb caixes, traços de 3 mm.|Letras con cajas, trazos de 3 mm.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["On comença un gravat d'1 mm en un clauer de 4 mm?|¿Dónde empieza un grabado de 1 mm en un llavero de 4 mm?", "Per què el forat de l'anella no pot tocar la vora?|¿Por qué el agujero de la anilla no puede tocar el borde?"], nota: 'Oral, abans de sortir.|Oral, antes de salir.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "Mesura els clauers de casa: gruix i vora de l'anella.|Mide los llaveros de casa: grosor y borde de la anilla.", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: el meu clauer en paper|Ficha: mi llavero en papel', k: 'fitxa', intro: 'Dibuixa el clauer en paper quadriculat de 5 mm i respon.|Dibuja el llavero en papel cuadriculado de 5 mm y responde.',
      items: [{ q: 'Quines mides té el teu clauer (amplada × fondària)?|¿Qué medidas tiene tu llavero (anchura × fondo)?', sol: 'Per exemple, 40 × 25 mm (8 × 5 quadrets).|Por ejemplo, 40 × 25 mm (8 × 5 cuadritos).' },
        { q: "Quants mil·límetres de vora has deixat al forat de l'anella?|¿Cuántos milímetros de borde has dejado en el agujero de la anilla?", sol: 'Almenys 2-3 mm (mig quadret o més).|Al menos 2-3 mm (medio cuadrito o más).' },
        { q: "Quantes caixes necessita la teva inicial? Dibuixa-les.|¿Cuántas cajas necesita tu inicial? Dibújalas.", sol: 'Depèn de la lletra: L i T, 2; F i H, 3; E, 4.|Depende de la letra: L y T, 2; F y H, 3; E, 4.' },
        { q: "Si el clauer fa 4 mm i vols gravar 1 mm, a quina z comença el gravat?|Si el llavero mide 4 mm y quieres grabar 1 mm, ¿en qué z empieza el grabado?", sol: 'z = 3|z = 3' }] }]
  },
  /* ---------- Sessió 3 · Caixes i tasses ---------- */
  'm5-3': {
    obj: ["L'alumne/a construeix un recipient restant un forat a una peça sòlida i deixant fons.|El alumno/a construye un recipiente restando un agujero a una pieza sólida y dejando fondo.",
      "L'alumne/a calcula el gruix de la paret com la meitat de la diferència de diàmetres.|El alumno/a calcula el grosor de la pared como la mitad de la diferencia de diámetros.",
      "L'alumne/a dissenya una tapa que encaixa deixant un marge d'uns 0,5 mm per costat.|El alumno/a diseña una tapa que encaja dejando un margen de unos 0,5 mm por lado.",
      "L'alumne/a mesura recipients reals i en relaciona les mides amb el model.|El alumno/a mide recipientes reales y relaciona sus medidas con el modelo."],
    comp: ['Matemàtiques, sentit de la mesura: diàmetres, diferències i meitats en mm|Matemáticas, sentido de la medida: diámetros, diferencias y mitades en mm', 'Matemàtiques, sentit espacial: cossos buits, seccions i talls|Matemáticas, sentido espacial: cuerpos huecos, secciones y cortes',
      "Tecnologia i digitalització: disseny de recipients i peces que encaixen|Tecnología y digitalización: diseño de recipientes y piezas que encajan", 'Coneixement del medi: l\'hort escolar i la germinació de llavors|Conocimiento del medio: el huerto escolar y la germinación de semillas'],
    vocab: [['Recipient|Recipiente', 'Peça buida per guardar-hi coses.|Pieza hueca para guardar cosas.'], ['Paret|Pared', 'El plàstic dels costats del recipient.|El plástico de los lados del recipiente.'], ['Fons|Fondo', 'El plàstic de sota del recipient.|El plástico de debajo del recipiente.'],
      ['Tall (secció)|Corte (sección)', "Com es veu una peça tallada pel mig.|Cómo se ve una pieza cortada por el medio."], ['Tap|Tapón', "La part de la tapa que entra a l'obertura.|La parte de la tapa que entra en la abertura."], ['Marge (folgança)|Margen (holgura)', "L'espai de més que deixem perquè una peça hi entri.|El espacio de más que dejamos para que una pieza entre."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Caixes i tasses»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Cajas y tazas»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Gots i tasses de diferents mides i regles, un per parella|Vasos y tazas de distintos tamaños y reglas, uno por pareja'],
      imprimir: ['Fitxa: mesura un recipient|Ficha: mide un recipiente'], prep: ["Recollir gots, tasses i alguna capsa amb tapa (de plàstic, millor que de vidre).|Recoger vasos, tazas y alguna caja con tapa (de plástico, mejor que de vidrio).", 'Provar el repte de la nansa: cal girar l\'anell 90° en x.|Probar el reto del asa: hay que girar el anillo 90° en x.', "Si l'hort de l'escola està en marxa, parlar amb qui el porta per lligar-hi els gotets.|Si el huerto de la escuela está en marcha, hablar con quien lo lleva para relacionar los vasitos."] },
    plan: [
      { min: 5, t: "L'hort i la capsa dels tresors|El huerto y la caja de los tesoros", fase: 'inici', fa: "Presenta els encàrrecs i ensenya una tassa real tallada (o un dibuix tallat). Pregunta com la farien al taller amb el que saben.|Presenta los encargos y enseña una taza real cortada (o un dibujo cortado). Pregunta cómo la harían en el taller con lo que saben.",
        diu: ['Quines dues peces necessito per fer una tassa?|¿Qué dos piezas necesito para hacer una taza?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Parets, fons i tapes|Paredes, fondos y tapas', fase: 'teoria', fa: "Explica la tassa com a cilindre menys cilindre. Calculeu junts el gruix de la paret amb l'animació, mostra la tassa tallada per veure el fons i acaba amb la tapa i el marge.|Explica la taza como cilindro menos cilindro. Calculad juntos el grosor de la pared con la animación, muestra la taza cortada para ver el fondo y acaba con la tapa y el margen.",
        diu: ['Si la tassa fa 40 i el forat 36, quant fa la paret?|Si la taza mide 40 y el agujero 36, ¿cuánto mide la pared?', 'Per què el tap no pot fer exactament 56 mm?|¿Por qué el tapón no puede medir exactamente 56 mm?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'Mesura una tassa de veritat|Mide una taza de verdad', fase: 'desconnectat', fa: "Per parelles mesuren un got o una tassa: diàmetre de fora i de dins, calculen la paret i observen el fons. Ho apunten a la fitxa.|Por parejas miden un vaso o una taza: diámetro de fuera y de dentro, calculan la pared y observan el fondo. Lo apuntan en la ficha.",
        diu: ['El fons és més gruixut que la paret? Per què?|¿El fondo es más grueso que la pared? ¿Por qué?'], slides: ['s8'], app: 'Encara no: gots, regles i fitxa.|Todavía no: vasos, reglas y ficha.', org: 'Per parelles|Por parejas' },
      { min: 22, t: "A l'ordinador: tassa, nansa, capsa i tapa|En el ordenador: taza, asa, caja y tapa", fase: 'ordinador', fa: "Fan la sessió a l'app. Passa per les taules a la nansa (cal girar l'anell) i a la tapa (cal posar el tap a z = 2). Recorda que el forat de dins ha de ser més alt que la tassa.|Hacen la sesión en la app. Pasa por las mesas en el asa (hay que girar el anillo) y en la tapa (hay que poner el tapón en z = 2). Recuerda que el agujero de dentro tiene que ser más alto que la taza.",
        diu: ["Mira-la amb Resultat: té fons?|Mírala con Resultado: ¿tiene fondo?", "Qui treu el tros de nansa que entra a la tassa?|¿Quién quita el trozo de asa que entra en la taza?"], slides: ['s9', 's10', 's11'], app: "Sessió «Caixes i tasses», fins a «Un recipient a mida».|Sesión «Cajas y tazas», hasta «Un recipiente a medida».", org: 'Individual|Individual' },
      { min: 8, t: 'Un recipient a mida|Un recipiente a medida', fase: 'crea', fa: "Cada alumne/a pensa una cosa seva per guardar, en mesura la mida (o l'estima) i dissenya el recipient amb parets i fons de 2 mm.|Cada alumno/a piensa en algo suyo para guardar, mide su tamaño (o lo estima) y diseña el recipiente con paredes y fondo de 2 mm.",
        diu: ["Hi cabrà el que hi vols guardar? Com ho saps?|¿Cabrá lo que quieres guardar? ¿Cómo lo sabes?"], slides: ['s12'], app: 'Pas «Un recipient a mida».|Paso «Un recipiente a medida».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa el càlcul de la paret, el fons i el marge de la tapa. Tiquet de sortida.|Repasa el cálculo de la pared, el fondo y el margen de la tapa. Ticket de salida.",
        diu: ['Expliqueu el truc de la tassa en una frase.|Explicad el truco de la taza en una frase.'], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["El forat de dins comença a z = 0 i la tassa queda sense fons.|El agujero de dentro empieza en z = 0 y la taza queda sin fondo.", "Que miri el Resultat des de sota o la tassa tallada: el forat ha de començar a z = 2.|Que mire el Resultado desde abajo o la taza cortada: el agujero tiene que empezar en z = 2."],
      ["El forat és més curt que la tassa i no l'obre per dalt.|El agujero es más corto que la taza y no la abre por arriba.", 'Que el faci més alt (50 mm o més): ha de sobresortir per dalt.|Que lo haga más alto (50 mm o más): tiene que sobresalir por arriba.'],
      ['Resta els diàmetres però no divideix entre 2.|Resta los diámetros pero no divide entre 2.', "Dibuixeu el tall a la pissarra: la diferència es reparteix entre la paret de l'esquerra i la de la dreta.|Dibujad el corte en la pizarra: la diferencia se reparte entre la pared de la izquierda y la de la derecha."],
      ["Fa el tap exactament de la mida de l'obertura.|Hace el tapón exactamente de la medida de la abertura.", "Recorda-li que les peces impreses no surten exactes: sense marge, el tap no entraria. 1 mm menys en total.|Recuérdale que las piezas impresas no salen exactas: sin margen, el tapón no entraría. 1 mm menos en total."]],
    diff: { mes: "Fer una capsa amb compartiments (dos forats separats per una paret de 2 mm) o un gotet amb forat de desguàs al fons per a l'hort.|Hacer una caja con compartimentos (dos agujeros separados por una pared de 2 mm) o un vasito con agujero de desagüe en el fondo para el huerto.",
      menys: "Treballar només la tassa i la capsa, amb els números escrits a la pissarra (forat 36 o 56 × 36, z = 2). Fer la tapa junts.|Trabajar solo la taza y la caja, con los números escritos en la pizarra (agujero 36 o 56 × 36, z = 2). Hacer la tapa juntos." },
    aval: { ticket: ['Un got fa 50 mm per fora i 46 per dins. Quant fa la paret?|Un vaso mide 50 mm por fuera y 46 por dentro. ¿Cuánto mide la pared?', "Per què el tap d'una tapa ha de ser una mica més petit que l'obertura?|¿Por qué el tapón de una tapa tiene que ser un poco más pequeño que la abertura?"],
      rubric: [['Recipient amb fons|Recipiente con fondo', 'Fa el forat més alt que la peça i a z = 2.|Hace el agujero más alto que la pieza y en z = 2.', 'Necessita ajuda per deixar el fons o obrir-lo per dalt.|Necesita ayuda para dejar el fondo o abrirlo por arriba.'],
        ['Gruix de la paret|Grosor de la pared', 'Calcula la paret amb (fora − dins) ÷ 2.|Calcula la pared con (fuera − dentro) ÷ 2.', 'Fa la resta però no la divideix entre dos.|Hace la resta pero no la divide entre dos.'],
        ['Encaix de la tapa|Encaje de la tapa', 'Deixa un marge i sap explicar per què.|Deja un margen y sabe explicar por qué.', "Fa el tap justet o massa petit.|Hace el tapón justito o demasiado pequeño."]] },
    casa: "Busqueu a casa un recipient amb tapa (un pot, una carmanyola). Mesureu l'obertura i el tap: quant marge hi ha? Com encaixa: a pressió, enroscat, amb una vora?|Buscad en casa un recipiente con tapa (un bote, un táper). Medid la abertura y el tapón: ¿cuánto margen hay? ¿Cómo encaja: a presión, enroscado, con un borde?",
    intro: "Sessió molt manipulativa i amb molta matemàtica de mesura: diferències, meitats i marges. El recipient és la base del projecte del porta-llapis de la unitat 6, així que val la pena que el truc del forat amb fons quedi ben après.|Sesión muy manipulativa y con mucha matemática de medida: diferencias, mitades y márgenes. El recipiente es la base del proyecto del portalápices de la unidad 6, así que vale la pena que el truco del agujero con fondo quede bien aprendido.",
    claus: ["Recipient = peça sòlida − forat més estret que comença a z = 2.|Recipiente = pieza sólida − agujero más estrecho que empieza en z = 2.", 'Gruix de la paret = (fora − dins) ÷ 2.|Grosor de la pared = (fuera − dentro) ÷ 2.', 'El forat de dins ha de ser més alt que el recipient per obrir-lo per dalt.|El agujero de dentro tiene que ser más alto que el recipiente para abrirlo por arriba.', 'Una tapa encaixa amb un marge d\'uns 0,5 mm per costat.|Una tapa encaja con un margen de unos 0,5 mm por lado.'],
    prev: ['Saber fer forats passants i clots (sessions anteriors).|Saber hacer agujeros pasantes y hoyos (sesiones anteriores).', 'Saber girar una peça a la pestanya Gir (unitat 3).|Saber girar una pieza en la pestaña Giro (unidad 3).', 'Saber restar i fer la meitat de nombres fins a 100.|Saber restar y hacer la mitad de números hasta 100.'],
    faq: [["Per què el forat ha de començar a z = 2 i no a z = 1?|¿Por qué el agujero tiene que empezar en z = 2 y no en z = 1?", "Amb 1 mm el fons seria massa prim i es podria trencar o deixar passar l'aigua. Al taller fem servir 2 mm com a mínim.|Con 1 mm el fondo sería demasiado fino y se podría romper o dejar pasar el agua. En el taller usamos 2 mm como mínimo."],
      ["Un gotet imprès pot portar aigua?|¿Un vasito impreso puede llevar agua?", "Per a l'hort, sí: a més se li sol fer un forat de desguàs. Les peces impreses poden tenir petits porus entre capes, així que per beure no es recomanen.|Para el huerto, sí: además se le suele hacer un agujero de desagüe. Las piezas impresas pueden tener pequeños poros entre capas, así que para beber no se recomiendan."],
      ['Per què 0,5 mm de marge?|¿Por qué 0,5 mm de margen?', "Les impressores no són perfectes: les peces poden sortir unes dècimes de mil·límetre més grosses o més petites. Amb 0,5 mm per costat, el tap entra sense ballar gaire.|Las impresoras no son perfectas: las piezas pueden salir unas décimas de milímetro más gruesas o más pequeñas. Con 0,5 mm por lado, el tapón entra sin bailar mucho."]],
    tec: [['L\'anell de la nansa queda ajagut.|El anillo del asa queda tumbado.', "A la pestanya Gir, poseu 90 a la x (o toqueu el + sis vegades).|En la pestaña Giro, poned 90 en la x (o tocad el + seis veces)."],
      ['La tassa sembla massissa a la vista normal.|La taza parece maciza en la vista normal.', "En mode d'edició el forat es dibuixa ratllat a dins. Toqueu Resultat per veure-la buida.|En modo de edición el agujero se dibuja rayado dentro. Tocad Resultado para verla hueca."],
      ["El tap de la tapa queda dins de la capsa.|El tapón de la tapa queda dentro de la caja.", "Comproveu la x del tap: ha de ser 35 (a sobre de la tapa), no −35 (a sobre de la capsa).|Comprobad la x del tapón: tiene que ser 35 (encima de la tapa), no −35 (encima de la caja)."]],
    extra: ["Fer gotets amb forat de desguàs i plantar-hi llavors de l'hort.|Hacer vasitos con agujero de desagüe y plantar semillas del huerto.", 'Comparar el volum (cm³) d\'una tassa massissa i d\'una de buida: quant plàstic estalviem?|Comparar el volumen (cm³) de una taza maciza y de una hueca: ¿cuánto plástico ahorramos?', 'Dissenyar una capsa per a un objecte concret de l\'aula mesurant-lo abans.|Diseñar una caja para un objeto concreto del aula midiéndolo antes.'],
    trans: ['Sessió següent: projecte del segell (mirall, relleu i gravat).|Sesión siguiente: proyecto del sello (espejo, relieve y grabado).', 'Coneixement del medi: la germinació i el reg a l\'hort.|Conocimiento del medio: la germinación y el riego en el huerto.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Caixes i tasses|Cajas y tazas', x: 'Recipients amb parets, fons i tapa|Recipientes con paredes, fondo y tapa', nota: "Presenta els encàrrecs: gotets per a l'hort i la capsa dels tresors.|Presenta los encargos: vasitos para el huerto y la caja de los tesoros." },
      { id: 's2', k: 'pregunta', t: 'Com faries una tassa al taller?|¿Cómo harías una taza en el taller?', x: 'Pista: ja saps fer forats.|Pista: ya sabes hacer agujeros.', nota: "Que arribin a la idea del cilindre gran menys un cilindre més petit.|Que lleguen a la idea del cilindro grande menos un cilindro más pequeño." },
      { id: 's3', k: 'media', t: 'Cilindre menys cilindre|Cilindro menos cilindro', x: 'El forat buida la tassa per dins.|El agujero vacía la taza por dentro.', media: { k: 'model', model: TASSA, mode: 'edit' }, nota: "Gira-la: el forat és més alt que la tassa i no arriba a baix.|Gírala: el agujero es más alto que la taza y no llega abajo." },
      { id: 's4', k: 'anim', t: 'El gruix de la paret|El grosor de la pared', anim: 'm5paret', x: '(fora − dins) ÷ 2|(fuera − dentro) ÷ 2', nota: 'Feu més exemples: 50 i 46, 30 i 24.|Haced más ejemplos: 50 y 46, 30 y 24.' },
      { id: 's5', k: 'media', t: 'La tassa tallada|La taza cortada', x: 'Paret de 2 mm i fons de 2 mm.|Pared de 2 mm y fondo de 2 mm.', media: { k: 'model', model: TALL }, nota: 'El tall és un altre forat (una caixa) que treu la meitat de davant.|El corte es otro agujero (una caja) que quita la mitad de delante.' },
      { id: 's6', k: 'media', t: 'La capsa|La caja', x: 'Caixa de 60 × 40 menys forat de 56 × 36.|Caja de 60 × 40 menos agujero de 56 × 36.', media: { k: 'model', model: CAPSA }, nota: 'El mateix càlcul: (60 − 56) ÷ 2 = 2 mm.|El mismo cálculo: (60 − 56) ÷ 2 = 2 mm.' },
      { id: 's7', k: 'anim', t: 'La tapa i el marge|La tapa y el margen', anim: 'm5tapa', x: 'Un tap justet no entra; amb 0,5 mm de marge, sí.|Un tapón justito no entra; con 0,5 mm de margen, sí.', nota: "Si teniu una carmanyola, ensenyeu com encaixa la tapa.|Si tenéis un táper, enseñad cómo encaja la tapa." },
      { id: 's8', k: 'activitat', t: 'Mesura una tassa|Mide una taza', timer: 7, punts: ['Diàmetre de fora i de dins.|Diámetro de fuera y de dentro.', 'Calcula la paret.|Calcula la pared.', 'Observa el fons.|Observa el fondo.'], nota: 'Per parelles, amb la fitxa.|Por parejas, con la ficha.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['La tassa i la nansa.|La taza y el asa.', 'La capsa dels tresors.|La caja de los tesoros.', 'La tapa que encaixa.|La tapa que encaja.'], nota: 'Recorda: forat a z = 2 i més alt que el recipient.|Recuerda: agujero en z = 2 y más alto que el recipiente.' },
      { id: 's10', k: 'media', t: 'La nansa|El asa', x: "Un anell girat 90° en x, enganxat al costat.|Un anillo girado 90° en x, pegado al lado.", media: { k: 'model', model: NANSA }, nota: "El tros d'anell que entra a la tassa el treu el forat: els forats buiden totes les peces.|El trozo de anillo que entra en la taza lo quita el agujero: los agujeros vacían todas las piezas." },
      { id: 's11', k: 'pregunta', t: "L'obertura fa 56 × 36 mm. De quina mida fas el tap?|La abertura mide 56 × 36 mm. ¿De qué medida haces el tapón?", x: 'Pista: 0,5 mm de marge per costat.|Pista: 0,5 mm de margen por lado.', nota: 'Resposta: 55 × 35 mm.|Respuesta: 55 × 35 mm.' },
      { id: 's12', k: 'repte', t: 'Un recipient a mida|Un recipiente a medida', punts: ['Per guardar una cosa teva.|Para guardar algo tuyo.', 'Parets i fons de 2 mm.|Paredes y fondo de 2 mm.', 'Base plana i una sola peça.|Base plana y una sola pieza.'], nota: "Que mesurin o estimin el que hi volen guardar abans de començar.|Que midan o estimen lo que quieren guardar antes de empezar." },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Recipient = sòlid − forat que comença a z = 2.|Recipiente = sólido − agujero que empieza en z = 2.', 'Paret = (fora − dins) ÷ 2.|Pared = (fuera − dentro) ÷ 2.', "Tapa: el tap, 1 mm més petit que l'obertura.|Tapa: el tapón, 1 mm más pequeño que la abertura."], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Un got de 50 per fora i 46 per dins: paret?|Un vaso de 50 por fuera y 46 por dentro: ¿pared?', 'Per què el tap ha de ser més petit?|¿Por qué el tapón tiene que ser más pequeño?'], nota: 'Per escrit, al darrere de la fitxa.|Por escrito, detrás de la ficha.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "Mesura l'obertura i el tap d'un pot de casa: quant marge hi ha?|Mide la abertura y el tapón de un bote de casa: ¿cuánto margen hay?", nota: 'Proposta opcional.|Propuesta opcional.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: mesura un recipient|Ficha: mide un recipiente', k: 'fitxa', intro: 'Mesura un got o una tassa amb el regle i calcula.|Mide un vaso o una taza con la regla y calcula.',
      items: [{ q: 'Diàmetre de fora: ____ mm. Diàmetre de dins: ____ mm.|Diámetro de fuera: ____ mm. Diámetro de dentro: ____ mm.', sol: 'Depèn del recipient (per exemple, 80 i 74 mm).|Depende del recipiente (por ejemplo, 80 y 74 mm).' },
        { q: 'Gruix de la paret = (fora − dins) ÷ 2 = ____ mm|Grosor de la pared = (fuera − dentro) ÷ 2 = ____ mm', sol: 'Per exemple, (80 − 74) ÷ 2 = 3 mm.|Por ejemplo, (80 − 74) ÷ 2 = 3 mm.' },
        { q: 'Al taller, una tassa de 40 mm amb paret de 2 mm: quin forat li fas?|En el taller, una taza de 40 mm con pared de 2 mm: ¿qué agujero le haces?', sol: '40 − 2 − 2 = 36 mm|40 − 2 − 2 = 36 mm' },
        { q: "Una capsa té una obertura de 56 × 36 mm. De quina mida fas el tap de la tapa?|Una caja tiene una abertura de 56 × 36 mm. ¿De qué medida haces el tapón de la tapa?", sol: '55 × 35 mm (0,5 mm de marge per costat).|55 × 35 mm (0,5 mm de margen por lado).' }] }]
  },
  /* ---------- Sessió 4 · Projecte: el segell ---------- */
  'm5-4': {
    obj: ["L'alumne/a explica que un segell imprimeix el dibuix emmirallat i ho té en compte al disseny.|El alumno/a explica que un sello imprime el dibujo reflejado y lo tiene en cuenta en el diseño.",
      "L'alumne/a fa servir l'eina Mirall seleccionant només les peces que cal girar.|El alumno/a usa la herramienta Espejo seleccionando solo las piezas que hay que girar.",
      "L'alumne/a distingeix formes simètriques i no simètriques respecte d'un eix vertical.|El alumno/a distingue formas simétricas y no simétricas respecto a un eje vertical.",
      "L'alumne/a dissenya un segell complet (mànec, placa i dibuix) en relleu o gravat i el desa al portafoli.|El alumno/a diseña un sello completo (mango, placa y dibujo) en relieve o grabado y lo guarda en el portafolio."],
    comp: ["Matemàtiques, sentit espacial: simetria i reflexió respecte d'un eix|Matemáticas, sentido espacial: simetría y reflexión respecto a un eje", 'Matemàtiques, sentit espacial: vistes (la cara del segell a la vista de dalt)|Matemáticas, sentido espacial: vistas (la cara del sello en la vista de arriba)',
      "Tecnologia i digitalització: projecte de disseny amb requisits i comprovacions|Tecnología y digitalización: proyecto de diseño con requisitos y comprobaciones", 'Llengua i cultura: l\'ex-libris i la cura dels llibres|Lengua y cultura: el ex libris y el cuidado de los libros'],
    vocab: [['Segell|Sello', 'Objecte que, amb tinta, imprimeix un dibuix sobre el paper.|Objeto que, con tinta, imprime un dibujo sobre el papel.'], ['Mirall (reflexió)|Espejo (reflexión)', "Girar una forma d'esquerra a dreta com en un mirall.|Girar una forma de izquierda a derecha como en un espejo."], ['Simètric|Simétrico', "Que té les dues meitats iguals i es veu igual al mirall.|Que tiene las dos mitades iguales y se ve igual en el espejo."],
      ['Eix de simetria|Eje de simetría', 'La línia que parteix una forma simètrica en dues meitats iguals.|La línea que parte una forma simétrica en dos mitades iguales.'], ['Ex-libris|Ex libris', 'Marca personal que es posa als llibres per dir de qui són.|Marca personal que se pone en los libros para decir de quién son.'], ['Mànec|Mango', 'La part del segell per on s\'agafa.|La parte del sello por donde se coge.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Projecte: el segell»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Proyecto: el sello»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Fulls, retoladors gruixuts i miralls petits (o una finestra)|Hojas, rotuladores gruesos y espejos pequeños (o una ventana)'],
      imprimir: ['Fitxa: el meu segell|Ficha: mi sello', "Targetes: emmirallat o no?|Tarjetas: ¿reflejado o no?"], prep: ["Portar un segell de veritat i un tampó per ensenyar com surt el dibuix girat.|Traer un sello de verdad y un tampón para enseñar cómo sale el dibujo girado.", 'Imprimir i retallar les targetes.|Imprimir y recortar las tarjetas.', "Provar el repte de la F: cal seleccionar només les tres peces de la lletra.|Probar el reto de la F: hay que seleccionar solo las tres piezas de la letra."] },
    plan: [
      { min: 5, t: 'El segell de la biblioteca|El sello de la biblioteca', fase: 'inici', fa: "Presenta el projecte: un segell per a la biblioteca i un ex-libris personal. Fes una prova amb un segell de veritat: el dibuix surt girat!|Presenta el proyecto: un sello para la biblioteca y un ex libris personal. Haz una prueba con un sello de verdad: ¡el dibujo sale girado!",
        diu: ['Què ha passat amb la lletra del segell?|¿Qué ha pasado con la letra del sello?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Mirall, simetria i parts del segell|Espejo, simetría y partes del sello', fase: 'teoria', fa: "Explica el truc del mirall amb l'animació i l'eina Mirall en 3D. Classifiqueu formes simètriques i no simètriques. Compara relleu i gravat i mostra les parts del segell.|Explica el truco del espejo con la animación y la herramienta Espejo en 3D. Clasificad formas simétricas y no simétricas. Compara relieve y grabado y muestra las partes del sello.",
        diu: ["Quines lletres de l'abecedari es veuen igual al mirall?|¿Qué letras del abecedario se ven igual en el espejo?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'La lletra al revés|La letra al revés', fase: 'desconnectat', fa: "Escriuen la inicial, la repassen per darrere contra la finestra i la comproven al mirall. Després classifiquen les targetes: cal emmirallar o no?|Escriben la inicial, la repasan por detrás contra la ventana y la comprueban en el espejo. Después clasifican las tarjetas: ¿hay que reflejar o no?",
        diu: ['La teva inicial canvia al mirall?|¿Tu inicial cambia en el espejo?'], slides: ['s8'], app: 'Encara no: fulls, retoladors i targetes.|Todavía no: hojas, rotuladores y tarjetas.', org: 'Per parelles|Por parejas' },
      { min: 17, t: "A l'ordinador: L, F i mànec|En el ordenador: L, F y mango", fase: 'ordinador', fa: "Fan la sessió a l'app fins al projecte: trien el segell bo, troben les formes simètriques, emmirallen la L i la F i hi posen el mànec. El forat per penjar-lo és un repte extra.|Hacen la sesión en la app hasta el proyecto: eligen el sello bueno, encuentran las formas simétricas, reflejan la L y la F y le ponen el mango. El agujero para colgarlo es un reto extra.",
        diu: ["Has seleccionat només la lletra o també la placa?|¿Has seleccionado solo la letra o también la placa?"], slides: ['s9', 's10'], app: "Sessió «Projecte: el segell», fins a «El meu segell».|Sesión «Proyecto: el sello», hasta «Mi sello».", org: 'Individual|Individual' },
      { min: 15, t: 'El meu segell (ex-libris)|Mi sello (ex libris)', fase: 'crea', fa: "Projecte de la unitat: cada alumne/a dissenya el seu segell amb mànec, placa i dibuix, en relleu o gravat. Revisa amb ells els criteris (mirall, traços de 3 mm, una sola peça) abans de desar-lo.|Proyecto de la unidad: cada alumno/a diseña su sello con mango, placa y dibujo, en relieve o grabado. Revisa con ellos los criterios (espejo, trazos de 3 mm, una sola pieza) antes de guardarlo.",
        diu: ["Mira el teu segell des de dalt: com sortiria al paper?|Mira tu sello desde arriba: ¿cómo saldría en el papel?"], slides: ['s11', 's12'], app: 'Pas «El meu segell (ex-libris)».|Paso «Mi sello (ex libris)».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament i galeria|Cierre y galería', fase: 'tancament', fa: "Feu una galeria ràpida: alguns alumnes ensenyen el seu segell a la pissarra i la resta diu com sortiria al paper. Tiquet de sortida.|Haced una galería rápida: algunos alumnos enseñan su sello en la pizarra y el resto dice cómo saldría en el papel. Ticket de salida.",
        diu: ['Com sortirà al paper aquest segell?|¿Cómo saldrá en el papel este sello?'], slides: ['s13', 's14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Emmiralla també la placa (o tot el segell) i creu que no ha canviat res.|Refleja también la placa (o todo el sello) y cree que no ha cambiado nada.", "La placa és simètrica i no canvia, però el que importa és la lletra. Que comprovi a la vista de dalt cap on mira el pal de la F.|La placa es simétrica y no cambia, pero lo que importa es la letra. Que compruebe en la vista de arriba hacia dónde mira el palo de la F."],
      ['Fa servir el mirall en y i la lletra queda de cap per avall.|Usa el espejo en y y la letra queda boca abajo.', "El mirall d'un segell és d'esquerra a dreta: Mirall → x. Desfer i tornar-ho a fer.|El espejo de un sello es de izquierda a derecha: Espejo → x. Deshacer y volver a hacerlo."],
      ['Posa el mànec però la placa queda flotant o enfonsada.|Pone el mango pero la placa queda flotando o hundida.', "La placa ha de començar on acaba el mànec: si el mànec fa 26 mm, la placa va a z = 26.|La placa tiene que empezar donde acaba el mango: si el mango mide 26 mm, la placa va en z = 26."],
      ["Fa un dibuix amb traços molt prims o peces que no es toquen.|Hace un dibujo con trazos muy finos o piezas que no se tocan.", "Recorda la regla dels 3 mm i la comprovació «És una sola peça»: totes les parts s'han de tocar.|Recuerda la regla de los 3 mm y la comprobación «Es una sola pieza»: todas las partes se tienen que tocar."]],
    diff: { mes: "Fer un segell amb dues lletres o amb una paraula curta (cal emmirallar-ne l'ordre i cada lletra), o combinar relleu i gravat.|Hacer un sello con dos letras o con una palabra corta (hay que reflejar el orden y cada letra), o combinar relieve y grabado.",
      menys: "Fer el segell amb una forma simètrica (cor, estrella) i deixar la lletra per a més endavant. Fer el mànec junts a la pissarra.|Hacer el sello con una forma simétrica (corazón, estrella) y dejar la letra para más adelante. Hacer el mango juntos en la pizarra." },
    aval: { ticket: ['Com ha de ser la R d\'un segell perquè surti bé al paper?|¿Cómo tiene que ser la R de un sello para que salga bien en el papel?', 'Digues una forma que no cal emmirallar i per què.|Di una forma que no hace falta reflejar y por qué.'],
      rubric: [['Mirall|Espejo', 'Emmiralla el dibuix i explica per què cal fer-ho.|Refleja el dibujo y explica por qué hay que hacerlo.', "Fa servir el mirall amb ajuda o s'oblida d'alguna peça.|Usa el espejo con ayuda o se olvida de alguna pieza."],
        ['Simetria|Simetría', 'Reconeix formes simètriques i les fa servir sense emmirallar.|Reconoce formas simétricas y las usa sin reflejar.', 'Confon formes simètriques i no simètriques.|Confunde formas simétricas y no simétricas.'],
        ['Projecte complet|Proyecto completo', 'Mànec, placa i dibuix connectats, amb traços de 3 mm.|Mango, placa y dibujo conectados, con trazos de 3 mm.', 'Hi falta alguna part o hi ha peces que no es toquen.|Falta alguna parte o hay piezas que no se tocan.']] },
    casa: "Busqueu a casa coses que surtin «al revés»: el reflex en una cullera, l'ambulància escrita al revés perquè es llegeixi pel retrovisor, una samarreta estampada… Dibuixeu-ne una.|Buscad en casa cosas que salgan «al revés»: el reflejo en una cuchara, la ambulancia escrita al revés para que se lea por el retrovisor, una camiseta estampada… Dibujad una.",
    intro: "Projecte de la unitat: el segell reuneix tot el que han après (forats per gravar, peces en relleu, mides i col·locació) i hi afegeix un repte de pensament espacial molt potent, la reflexió. Deixeu-los temps per al projecte i per a la galeria final.|Proyecto de la unidad: el sello reúne todo lo que han aprendido (agujeros para grabar, piezas en relieve, medidas y colocación) y añade un reto de pensamiento espacial muy potente, la reflexión. Dejadles tiempo para el proyecto y para la galería final.",
    claus: ["Un segell imprimeix el dibuix emmirallat: el dissenyem girat amb Mirall → x.|Un sello imprime el dibujo reflejado: lo diseñamos girado con Espejo → x.", "Les formes simètriques no cal girar-les.|Las formas simétricas no hace falta girarlas.", 'Relleu: el dibuix agafa la tinta. Gravat: el dibuix queda en blanc.|Relieve: el dibujo coge la tinta. Grabado: el dibujo queda en blanco.', "El segell es dissenya com s'imprimirà: mànec a baix, dibuix a dalt.|El sello se diseña como se imprimirá: mango abajo, dibujo arriba."],
    prev: ['Saber gravar amb forats i posar peces en relleu (sessió «Un clauer»).|Saber grabar con agujeros y poner piezas en relieve (sesión «Un llavero»).', 'Haver vist la simetria i el mirall a la unitat 4.|Haber visto la simetría y el espejo en la unidad 4.', 'Saber seleccionar diverses peces alhora.|Saber seleccionar varias piezas a la vez.'],
    faq: [["Per què el mànec va a baix si quan el fem servir va a dalt?|¿Por qué el mango va abajo si cuando lo usamos va arriba?", "Perquè el dissenyem tal com l'imprimirà la Nuvi: el dibuix a dalt surt més ben definit. Per fer-lo servir, només cal girar-lo.|Porque lo diseñamos tal como lo imprimirá Nuvi: el dibujo arriba sale mejor definido. Para usarlo, solo hay que girarlo."],
      ['Funciona de veritat un segell imprès?|¿Funciona de verdad un sello impreso?', "Sí, amb un tampó de tinta. La superfície de plàstic és dura i el dibuix pot sortir una mica irregular: premeu fort i sobre una superfície tova (una llibreta).|Sí, con un tampón de tinta. La superficie de plástico es dura y el dibujo puede salir un poco irregular: apretad fuerte y sobre una superficie blanda (una libreta)."],
      ["Com s'imprimeix la placa que sobresurt del mànec?|¿Cómo se imprime la placa que sobresale del mango?", "La placa queda a l'aire per sota: la impressora hi posa suports que després es treuen. A la unitat 6 veurem com evitar-los o reduir-los.|La placa queda en el aire por debajo: la impresora pone soportes que después se quitan. En la unidad 6 veremos cómo evitarlos o reducirlos."]],
    tec: [["No sé seleccionar només la F.|No sé seleccionar solo la F.", "Toqueu una peça de la F, després «Selecciona'n més» i les altres dues. L'inspector ha de dir «3 peces».|Tocad una pieza de la F, después «Selecciona más» y las otras dos. El inspector tiene que decir «3 piezas»."],
      ["El Mirall no fa res.|El Espejo no hace nada.", "Si la forma és simètrica, no canvia: és normal. Comproveu que hi hagi peces seleccionades i que trieu l'eix x.|Si la forma es simétrica, no cambia: es normal. Comprobad que haya piezas seleccionadas y que elegís el eje x."],
      ['Després de pujar la placa, la F queda a sota.|Después de subir la placa, la F queda debajo.', "Cal pujar la placa i la F alhora (seleccioneu-ho tot amb «Totes» abans de canviar la z).|Hay que subir la placa y la F a la vez (seleccionadlo todo con «Todas» antes de cambiar la z)."]],
    extra: ["Fer una exposició d'ex-libris i provar-los amb tinta si s'han pogut imprimir.|Hacer una exposición de ex libris y probarlos con tinta si se han podido imprimir.", 'Escriure missatges secrets en mirall perquè els companys els llegeixin amb un mirall.|Escribir mensajes secretos en espejo para que los compañeros los lean con un espejo.', "Cercar l'eix de simetria de les lletres de l'abecedari i fer-ne una classificació.|Buscar el eje de simetría de las letras del abecedario y hacer una clasificación."],
    trans: ['Unitat següent: del model a l\'objecte, com treballa una impressora 3D.|Unidad siguiente: del modelo al objeto, cómo trabaja una impresora 3D.', 'Matemàtiques: la simetria axial i les transformacions al pla.|Matemáticas: la simetría axial y las transformaciones en el plano.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Projecte: el segell|Proyecto: el sello', x: "Un segell per a la biblioteca i el teu ex-libris|Un sello para la biblioteca y tu ex libris", nota: "Presenta el projecte de la unitat i ensenya un segell de veritat.|Presenta el proyecto de la unidad y enseña un sello de verdad." },
      { id: 's2', k: 'pregunta', t: 'Per què la lletra del segell surt girada?|¿Por qué la letra del sello sale girada?', x: 'Prova-ho amb un segell i un tampó.|Pruébalo con un sello y un tampón.', nota: 'Deixa que ho descobreixin: el paper és com un mirall de la cara del segell.|Deja que lo descubran: el papel es como un espejo de la cara del sello.' },
      { id: 's3', k: 'anim', t: 'El truc del segell|El truco del sello', anim: 'm5mirall', x: 'La F del segell va emmirallada.|La F del sello va reflejada.', nota: "Fes notar que el pal de la F canvia de costat.|Haz notar que el palo de la F cambia de lado." },
      { id: 's4', k: 'media', t: "L'eina Mirall|La herramienta Espejo", x: 'A l\'esquerra, la L normal; a la dreta, emmirallada.|A la izquierda, la L normal; a la derecha, reflejada.', media: { k: 'model', model: LL, view: 'top' }, nota: 'Demostra a la pissarra: selecciona les peces i Mirall → x.|Demuestra en la pizarra: selecciona las piezas y Espejo → x.' },
      { id: 's5', k: 'pregunta', t: 'Quines formes es veuen igual al mirall?|¿Qué formas se ven igual en el espejo?', x: 'Un cor, una L, una estrella, una F, una T, una A…|Un corazón, una L, una estrella, una F, una T, una A…', nota: 'Simètriques: cor, estrella, T, A. No simètriques: L, F.|Simétricas: corazón, estrella, T, A. No simétricas: L, F.' },
      { id: 's6', k: 'anim', t: 'Relleu o gravat|Relieve o grabado', anim: 'm5tinta', x: 'El relleu agafa la tinta; el gravat queda en blanc.|El relieve coge la tinta; el grabado queda en blanco.', nota: "Que triïn quina manera faran servir al projecte.|Que elijan qué manera usarán en el proyecto." },
      { id: 's7', k: 'media', t: 'Les parts del segell|Las partes del sello', x: 'Mànec, placa i dibuix (emmirallat).|Mango, placa y dibujo (reflejado).', media: { k: 'model', model: SEG }, nota: "Explica per què el mànec va a baix: així s'imprimirà.|Explica por qué el mango va abajo: así se imprimirá." },
      { id: 's8', k: 'activitat', t: 'La lletra al revés|La letra al revés', timer: 7, punts: ['Escriu la teva inicial.|Escribe tu inicial.', 'Repassa-la per darrere a contrallum.|Repásala por detrás a contraluz.', 'Classifica les targetes.|Clasifica las tarjetas.'], nota: 'Per parelles. Després, feu una classificació ràpida a la pissarra amb les targetes.|Por parejas. Las tarjetas se pueden usar para una clasificación rápida en la pizarra.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Tria el segell bo.|Elige el sello bueno.', 'Emmiralla la L i la F.|Refleja la L y la F.', 'Posa-hi el mànec.|Ponle el mango.'], nota: 'Recorda: selecciona només la lletra.|Recuerda: selecciona solo la letra.' },
      { id: 's10', k: 'media', t: 'La cara del segell, des de dalt|La cara del sello, desde arriba', x: 'Així ha de quedar la F: amb el pal a la dreta.|Así tiene que quedar la F: con el palo a la derecha.', media: { k: 'model', model: CARA, view: 'top' }, nota: "Ajuda per a qui s'encalli al repte de la F.|Ayuda para quien se atasque en el reto de la F." },
      { id: 's11', k: 'repte', t: 'El meu segell (ex-libris)|Mi sello (ex libris)', punts: ['Dibuix emmirallat o simètric.|Dibujo reflejado o simétrico.', 'Mànec, placa i dibuix.|Mango, placa y dibujo.', 'Traços de 3 mm i una sola peça.|Trazos de 3 mm y una sola pieza.'], nota: 'Projecte de la unitat: es desa al portafoli.|Proyecto de la unidad: se guarda en el portafolio.' },
      { id: 's12', k: 'concepte', t: 'Revisa abans de desar|Revisa antes de guardar', x: "Mira el segell des de dalt i imagina'l al paper. Les comprovacions han d'estar verdes.|Mira el sello desde arriba e imagínalo en el papel. Las comprobaciones tienen que estar en verde.", nota: 'Que un company el revisi i digui com sortiria al paper.|Que un compañero lo revise y diga cómo saldría en el papel.' },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['El segell imprimeix en mirall.|El sello imprime en espejo.', 'Les formes simètriques no canvien.|Las formas simétricas no cambian.', 'Relleu o gravat, amb mànec.|Relieve o grabado, con mango.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Com ha de ser la R del segell?|¿Cómo tiene que ser la R del sello?', 'Una forma que no cal emmirallar.|Una forma que no hace falta reflejar.'], nota: 'Oral, durant la galeria.|Oral, durante la galería.' },
      { id: 's15', k: 'concepte', t: 'A casa|En casa', x: "Busca coses escrites o dibuixades al revés i descobreix per què.|Busca cosas escritas o dibujadas al revés y descubre por qué.", nota: "Exemple clàssic: AMBULÀNCIA escrit al revés per llegir-lo pel retrovisor.|Ejemplo clásico: AMBULANCIA escrito al revés para leerlo por el retrovisor." }
    ],
    print: [
      { id: 'p1', t: 'Fitxa: el meu segell|Ficha: mi sello', k: 'fitxa', intro: 'Planifica el teu segell abans de fer-lo a l\'ordinador.|Planifica tu sello antes de hacerlo en el ordenador.',
        items: [{ q: 'Dibuixa el teu dibuix o inicial tal com vols que surti al paper.|Dibuja tu dibujo o inicial tal como quieres que salga en el papel.', sol: 'Dibuix lliure.|Dibujo libre.' },
          { q: 'Ara dibuixa com ha de ser a la cara del segell.|Ahora dibuja cómo tiene que ser en la cara del sello.', sol: "El mateix dibuix emmirallat (si no és simètric).|El mismo dibujo reflejado (si no es simétrico)." },
          { q: 'Relleu o gravat? Per què?|¿Relieve o grabado? ¿Por qué?', sol: 'Resposta oberta: relleu, el dibuix surt de color; gravat, el dibuix surt en blanc.|Respuesta abierta: relieve, el dibujo sale de color; grabado, el dibujo sale en blanco.' },
          { q: 'Mides: mànec ____ mm, placa ____ × ____ mm.|Medidas: mango ____ mm, placa ____ × ____ mm.', sol: 'Per exemple: mànec de 24 × 26 mm i placa de 40 × 40 × 5 mm.|Por ejemplo: mango de 24 × 26 mm y placa de 40 × 40 × 5 mm.' }] },
      { id: 'p2', t: "Targetes: emmirallat o no?|Tarjetas: ¿reflejado o no?", k: 'targetes', intro: "Retalleu-les i classifiqueu-les: cal emmirallar-la per al segell o no?|Recortadlas y clasificadlas: ¿hay que reflejarla para el sello o no?",
        items: [{ t: 'A|A', n: 1 }, { t: 'F|F', n: 1 }, { t: 'L|L', n: 1 }, { t: 'T|T', n: 1 }, { t: 'R|R', n: 1 }, { t: 'H|H', n: 1 }, { t: '7|7', n: 1 }, { t: '8|8', n: 1 }, { t: '♥|♥', n: 1 }, { t: '★|★', n: 1 }] }
    ]
  }
  };
})());

